import { Question } from '@/types/question';

const questions: Question[] = [
  { id: 'pg-advanced-l2-001', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you write a basic FOR loop in PL/pgSQL?', options: ['Use WHILE with a counter variable', 'Use FOR variable IN lower..upper LOOP ... END LOOP which iterates the variable through consecutive integer values from lower to upper inclusive, executing the loop body for each value', 'Use FOREACH to iterate over integers', 'Use REPEAT ... UNTIL syntax'], correctAnswer: 0, explanation: 'The FOR..IN loop in PL/pgSQL iterates through a range of integers. The loop variable is automatically declared as an integer and exists only within the loop scope. You can add BY step to change the increment. The loop variable is local to the loop and cannot be referenced outside it.', codeSnippet: "DO $$\nDECLARE\n  total INTEGER := 0;\nBEGIN\n  FOR i IN 1..10 LOOP\n    total := total + i;\n  END LOOP;\n  RAISE NOTICE 'Sum 1..10 = %', total;\n  -- Output: Sum 1..10 = 55\n\n  -- Reverse loop:\n  FOR i IN REVERSE 10..1 LOOP\n    RAISE NOTICE 'Countdown: %', i;\n  END LOOP;\n\n  -- Step by 2:\n  FOR i IN 1..10 BY 2 LOOP\n    RAISE NOTICE 'Odd: %', i; -- 1, 3, 5, 7, 9\n  END LOOP;\nEND;\n$$;", tags: ['advanced', 'plpgsql', 'for-loop', 'iteration'] },
  { id: 'pg-advanced-l2-002', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How does the FOR..IN query loop work in PL/pgSQL?', options: ['It loops over column names', 'FOR record IN SELECT ... LOOP iterates over each row returned by the query — the loop variable is automatically a record type containing the column values, allowing row-by-row processing of query results', 'It loops over table names', 'It loops a fixed number of times'], correctAnswer: 1, explanation: 'Query FOR loops iterate over the result set of a SQL query. The loop variable is implicitly declared as type RECORD and takes on the value of each successive row. This is the PL/pgSQL equivalent of a cursor-based loop but with simpler syntax. For large result sets, consider using RETURN QUERY instead for better performance.', codeSnippet: "CREATE FUNCTION list_expensive_products(min_price NUMERIC)\nRETURNS TABLE(name TEXT, price NUMERIC) AS $$\nDECLARE\n  r RECORD;\nBEGIN\n  FOR r IN\n    SELECT product_name, unit_price\n    FROM products\n    WHERE unit_price > min_price\n    ORDER BY unit_price DESC\n  LOOP\n    name := r.product_name;\n    price := r.unit_price;\n    RETURN NEXT;\n  END LOOP;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'plpgsql', 'for-in-query', 'record'] },
  { id: 'pg-advanced-l2-003', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'What is the WHILE loop syntax in PL/pgSQL?', options: ['WHILE condition DO ... END WHILE', 'LOOP WHILE condition ... END', 'WHILE condition LOOP ... END LOOP — which repeatedly executes the loop body as long as the boolean condition evaluates to true, checking the condition before each iteration', 'DO WHILE condition ... DONE'], correctAnswer: 2, explanation: 'WHILE loops check their condition before each iteration. If the condition is false initially, the loop body never executes. This is useful when the number of iterations is not known in advance. Be careful to ensure the condition eventually becomes false to avoid infinite loops. Use EXIT to break out of the loop early if needed.', codeSnippet: "DO $$\nDECLARE\n  n INTEGER := 1;\n  factorial BIGINT := 1;\nBEGIN\n  WHILE n <= 10 LOOP\n    factorial := factorial * n;\n    n := n + 1;\n  END LOOP;\n  RAISE NOTICE '10! = %', factorial;\n  -- Output: 10! = 3628800\nEND;\n$$;\n\n-- Practical example: retry logic\nCREATE FUNCTION retry_insert(val TEXT)\nRETURNS BOOLEAN AS $$\nDECLARE\n  attempts INTEGER := 0;\nBEGIN\n  WHILE attempts < 3 LOOP\n    BEGIN\n      INSERT INTO my_table(data) VALUES (val);\n      RETURN TRUE;\n    EXCEPTION WHEN unique_violation THEN\n      attempts := attempts + 1;\n      val := val || '_' || attempts;\n    END;\n  END LOOP;\n  RETURN FALSE;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'plpgsql', 'while-loop', 'control-flow'] },
  { id: 'pg-advanced-l2-004', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How does the FOREACH loop work with arrays in PL/pgSQL?', options: ['FOREACH iterates over rows in a table', 'FOREACH iterates over database schemas', 'FOREACH element IN ARRAY array_expression LOOP iterates over each element of a PostgreSQL array — executing the loop body once per array element with the loop variable set to the current element value', 'FOREACH iterates over function parameters'], correctAnswer: 3, explanation: 'FOREACH..IN ARRAY is specifically designed for iterating over array elements. Unlike FOR which works with integer ranges or queries, FOREACH directly iterates array contents. You can also use SLICE to iterate over sub-arrays. The loop variable must be declared with a compatible type to the array element type.', codeSnippet: "DO $$\nDECLARE\n  arr INTEGER[] := ARRAY[10, 20, 30, 40, 50];\n  elem INTEGER;\n  total INTEGER := 0;\nBEGIN\n  FOREACH elem IN ARRAY arr LOOP\n    total := total + elem;\n  END LOOP;\n  RAISE NOTICE 'Sum = %', total; -- 150\nEND;\n$$;\n\n-- SLICE for multi-dimensional arrays:\nDO $$\nDECLARE\n  m INTEGER[][] := ARRAY[[1,2],[3,4],[5,6]];\n  row INTEGER[];\nBEGIN\n  FOREACH row SLICE 1 IN ARRAY m LOOP\n    RAISE NOTICE 'Row: %', row;\n    -- [1,2], [3,4], [5,6]\n  END LOOP;\nEND;\n$$;", tags: ['advanced', 'plpgsql', 'foreach', 'arrays'] },
  { id: 'pg-advanced-l2-005', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'What does the EXIT statement do inside a PL/pgSQL loop?', options: ['EXIT terminates the entire function immediately and returns control to the caller', 'EXIT terminates the current loop iteration and moves to the next iteration', 'EXIT terminates the innermost loop — optionally with a WHEN condition (EXIT WHEN condition) or a label (EXIT label) to break out of a specific named loop, continuing execution after the END LOOP', 'EXIT rolls back the current transaction'], correctAnswer: 0, explanation: 'EXIT breaks out of the innermost enclosing loop by default. With EXIT label, it can break out of a named outer loop. EXIT WHEN provides a conditional break. This is equivalent to "break" in other languages. CONTINUE is the counterpart that skips to the next iteration (like "continue" in C/Java).', codeSnippet: "DO $$\nDECLARE\n  i INTEGER;\nBEGIN\n  -- Simple EXIT WHEN:\n  i := 0;\n  LOOP\n    i := i + 1;\n    EXIT WHEN i > 5;\n    RAISE NOTICE 'i = %', i;\n  END LOOP;\n\n  -- EXIT with label:\n  <<outer>>\n  FOR i IN 1..10 LOOP\n    FOR j IN 1..10 LOOP\n      IF i * j > 20 THEN\n        EXIT outer; -- breaks outer loop\n      END IF;\n    END LOOP;\n  END LOOP;\n  RAISE NOTICE 'Done at i=%, j=%', i, j;\nEND;\n$$;", tags: ['advanced', 'plpgsql', 'exit', 'loop-control'] },
  { id: 'pg-advanced-l2-006', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How does the CONTINUE statement work in PL/pgSQL loops?', options: ['CONTINUE resumes a paused transaction', 'CONTINUE restarts the loop from the beginning', 'CONTINUE skips the rest of the current loop iteration and jumps to the next iteration — optionally with WHEN condition (CONTINUE WHEN condition) or a label to target a specific enclosing loop', 'CONTINUE moves to the next function in a chain'], correctAnswer: 1, explanation: 'CONTINUE skips the remainder of the current loop iteration, proceeding to the next iteration check. Like EXIT, it supports WHEN for conditional skipping and labels for targeting outer loops. This is useful for filtering within loops without deep nesting of IF blocks.', codeSnippet: "DO $$\nBEGIN\n  FOR i IN 1..20 LOOP\n    -- Skip even numbers:\n    CONTINUE WHEN i % 2 = 0;\n    RAISE NOTICE 'Odd: %', i;\n  END LOOP;\n\n  -- With label:\n  <<process>>\n  FOR i IN 1..5 LOOP\n    FOR j IN 1..5 LOOP\n      CONTINUE process WHEN j = 3;\n      RAISE NOTICE '%, %', i, j;\n    END LOOP;\n  END LOOP;\nEND;\n$$;", tags: ['advanced', 'plpgsql', 'continue', 'loop-control'] },
  { id: 'pg-advanced-l2-007', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'What is the IF..ELSIF..ELSE conditional structure in PL/pgSQL?', options: ['IF condition THEN ... ELSIF condition THEN ... ELSE ... END IF — evaluates conditions in order and executes the block for the first true condition, or the ELSE block if none match, providing multi-branch conditional logic', 'IF condition BEGIN ... END', 'IF condition { ... } ELSE { ... }', 'CASE WHEN is the only conditional in PL/pgSQL'], correctAnswer: 2, explanation: 'IF..ELSIF..ELSE provides multi-branch conditional execution. Conditions are evaluated top-down and the first true branch executes. Note the spelling is ELSIF (not ELSEIF or ELSE IF). Each branch can contain any PL/pgSQL statements. The ELSE clause is optional but catches all unmatched cases.', codeSnippet: "CREATE FUNCTION grade_score(score INTEGER)\nRETURNS TEXT AS $$\nBEGIN\n  IF score >= 90 THEN\n    RETURN 'A';\n  ELSIF score >= 80 THEN\n    RETURN 'B';\n  ELSIF score >= 70 THEN\n    RETURN 'C';\n  ELSIF score >= 60 THEN\n    RETURN 'D';\n  ELSE\n    RETURN 'F';\n  END IF;\nEND;\n$$ LANGUAGE plpgsql;\n\nSELECT grade_score(85); -- 'B'\nSELECT grade_score(42); -- 'F'", tags: ['advanced', 'plpgsql', 'if-elsif', 'conditionals'] },
  { id: 'pg-advanced-l2-008', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How does the CASE statement work in PL/pgSQL as a control structure?', options: ['CASE in PL/pgSQL is identical to SQL CASE expressions', 'The PL/pgSQL CASE statement is a control structure (not an expression) that executes different statement blocks based on matching conditions — with simple CASE comparing a value and searched CASE evaluating boolean expressions, ending with END CASE', 'CASE only works with integer values', 'CASE replaces IF statements entirely'], correctAnswer: 3, explanation: 'PL/pgSQL has two forms: simple CASE (CASE expression WHEN value THEN statements) and searched CASE (CASE WHEN condition THEN statements). Unlike the SQL CASE expression, the PL/pgSQL CASE is a statement that executes code blocks. If no match is found and there is no ELSE clause, a CASE_NOT_FOUND exception is raised.', codeSnippet: "-- Simple CASE:\nCREATE FUNCTION describe_day(d INTEGER)\nRETURNS TEXT AS $$\nBEGIN\n  CASE d\n    WHEN 1 THEN RETURN 'Monday';\n    WHEN 2 THEN RETURN 'Tuesday';\n    WHEN 6, 7 THEN RETURN 'Weekend';\n    ELSE RETURN 'Midweek';\n  END CASE;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Searched CASE:\nCREATE FUNCTION categorize_temp(temp NUMERIC)\nRETURNS TEXT AS $$\nBEGIN\n  CASE\n    WHEN temp < 0 THEN RETURN 'Freezing';\n    WHEN temp < 20 THEN RETURN 'Cool';\n    WHEN temp < 30 THEN RETURN 'Warm';\n    ELSE RETURN 'Hot';\n  END CASE;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'plpgsql', 'case-statement', 'conditionals'] },
  { id: 'pg-advanced-l2-009', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you handle exceptions in PL/pgSQL?', options: ['Use TRY..CATCH blocks', 'Use ON ERROR RESUME NEXT', 'Use BEGIN ... EXCEPTION WHEN condition THEN handler ... END within a PL/pgSQL block — which catches specific error conditions and allows recovery or logging, with each EXCEPTION clause able to handle multiple error types', 'Exceptions cannot be caught in PL/pgSQL'], correctAnswer: 0, explanation: 'PL/pgSQL uses BEGIN..EXCEPTION..END blocks for error handling. When an exception occurs, the subtransaction is rolled back but the outer transaction survives. You can catch specific conditions (unique_violation, foreign_key_violation, etc.) or use OTHERS to catch all. Exception blocks add overhead because PostgreSQL creates a subtransaction (savepoint) for each block.', codeSnippet: "CREATE FUNCTION safe_insert(p_id INTEGER, p_name TEXT)\nRETURNS TEXT AS $$\nBEGIN\n  INSERT INTO customers(id, name)\n  VALUES (p_id, p_name);\n  RETURN 'Inserted';\nEXCEPTION\n  WHEN unique_violation THEN\n    RETURN 'Duplicate ID: ' || p_id;\n  WHEN not_null_violation THEN\n    RETURN 'Name cannot be null';\n  WHEN OTHERS THEN\n    RETURN 'Error: ' || SQLERRM;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- SQLSTATE codes:\n-- 23505 = unique_violation\n-- 23503 = foreign_key_violation\n-- 23502 = not_null_violation\n-- 22012 = division_by_zero", tags: ['advanced', 'plpgsql', 'exception-handling', 'error-handling'] },
  { id: 'pg-advanced-l2-010', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'What are the SQLSTATE and SQLERRM variables in PL/pgSQL exception handlers?', options: ['They are configuration parameters', 'They store SQL query plans', 'SQLSTATE contains the 5-character error code (e.g., 23505 for unique_violation) and SQLERRM contains the human-readable error message text — both are automatically set when an exception is caught in a PL/pgSQL EXCEPTION block', 'They are used for SQL injection prevention'], correctAnswer: 1, explanation: 'SQLSTATE and SQLERRM are special variables available only within exception handlers. SQLSTATE follows the SQL standard 5-character error code format (class + subclass). SQLERRM provides the descriptive error message. For more detailed error information, use GET STACKED DIAGNOSTICS to retrieve RETURNED_SQLSTATE, MESSAGE_TEXT, PG_EXCEPTION_DETAIL, PG_EXCEPTION_HINT, and PG_EXCEPTION_CONTEXT.', codeSnippet: "CREATE FUNCTION safe_divide(a NUMERIC, b NUMERIC)\nRETURNS TEXT AS $$\nDECLARE\n  result NUMERIC;\n  err_state TEXT;\n  err_msg TEXT;\n  err_detail TEXT;\nBEGIN\n  result := a / b;\n  RETURN result::TEXT;\nEXCEPTION WHEN OTHERS THEN\n  GET STACKED DIAGNOSTICS\n    err_state = RETURNED_SQLSTATE,\n    err_msg = MESSAGE_TEXT,\n    err_detail = PG_EXCEPTION_DETAIL;\n  RETURN format('Error [%s]: %s (%s)',\n    err_state, err_msg, err_detail);\nEND;\n$$ LANGUAGE plpgsql;\n\nSELECT safe_divide(10, 0);\n-- Error [22012]: division by zero ()", tags: ['advanced', 'plpgsql', 'sqlstate', 'sqlerrm', 'exception'] },
  { id: 'pg-advanced-l2-011', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you raise custom exceptions in PL/pgSQL?', options: ['Use THROW with an error message', 'Use SIGNAL with an error code', 'Use RAISE EXCEPTION with a format string — RAISE supports levels (DEBUG, LOG, INFO, NOTICE, WARNING, EXCEPTION) and format placeholders (%) for variable interpolation, with EXCEPTION level aborting the current transaction', 'Use ERROR() function call'], correctAnswer: 2, explanation: 'RAISE is the PL/pgSQL mechanism for sending messages and raising errors. The EXCEPTION level aborts the transaction. Lower levels (NOTICE, WARNING, etc.) just emit messages. You can set SQLSTATE with USING ERRCODE, add DETAIL, and HINT. The format string uses % as placeholder for subsequent arguments.', codeSnippet: "CREATE FUNCTION withdraw(acct_id INTEGER, amount NUMERIC)\nRETURNS NUMERIC AS $$\nDECLARE\n  balance NUMERIC;\nBEGIN\n  SELECT current_balance INTO balance\n  FROM accounts WHERE id = acct_id;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Account % not found', acct_id\n      USING ERRCODE = 'P0002',\n            HINT = 'Check the account ID';\n  END IF;\n\n  IF amount > balance THEN\n    RAISE EXCEPTION 'Insufficient funds: need %, have %',\n      amount, balance\n      USING ERRCODE = '22004',\n            DETAIL = 'Account: ' || acct_id;\n  END IF;\n\n  UPDATE accounts SET current_balance = balance - amount\n  WHERE id = acct_id;\n  RETURN balance - amount;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'plpgsql', 'raise-exception', 'custom-errors'] },
  { id: 'pg-advanced-l2-012', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'What is the difference between RAISE NOTICE and RAISE EXCEPTION?', options: ['RAISE NOTICE logs the message and continues execution normally — it is used for debugging and informational output, while RAISE EXCEPTION aborts the current transaction and raises an error that must be caught or will terminate the block', 'They are identical', 'RAISE NOTICE is for warnings, RAISE EXCEPTION is for logs', 'RAISE NOTICE throws a soft exception'], correctAnswer: 3, explanation: 'RAISE levels control both visibility and behavior. DEBUG/LOG go to the server log. INFO/NOTICE/WARNING are sent to the client. Only EXCEPTION level actually aborts execution and rolls back the current subtransaction. The client_min_messages setting controls which levels are shown to the client, while log_min_messages controls server log output.', codeSnippet: "DO $$\nBEGIN\n  RAISE DEBUG 'Debug message';    -- server log only\n  RAISE LOG 'Log message';         -- server log only\n  RAISE INFO 'Info message';       -- sent to client\n  RAISE NOTICE 'Notice message';   -- sent to client\n  RAISE WARNING 'Warning message'; -- sent to client\n\n  -- Only EXCEPTION aborts:\n  RAISE NOTICE 'This runs fine';\n  -- RAISE EXCEPTION 'This aborts!';\n  RAISE NOTICE 'This also runs';\nEND;\n$$;\n\n-- Control visibility:\nSET client_min_messages = 'warning';\n-- Now only WARNING and EXCEPTION shown to client", tags: ['advanced', 'plpgsql', 'raise-notice', 'raise-levels'] },
  { id: 'pg-advanced-l2-013', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'Triggers', question: 'What are the NEW and OLD record variables in PostgreSQL trigger functions?', options: ['NEW and OLD are table aliases for joins', 'NEW and OLD are special record variables in trigger functions — NEW contains the new row being inserted or the modified row for updates, while OLD contains the original row before update or the row being deleted, allowing triggers to inspect and modify data changes', 'NEW refers to the newest table, OLD to the oldest', 'They refer to new and old database connections'], correctAnswer: 0, explanation: 'NEW and OLD are automatically available in row-level trigger functions. For INSERT triggers, only NEW is available. For DELETE triggers, only OLD is available. For UPDATE triggers, both are available. In BEFORE triggers, modifying NEW changes what gets written. In AFTER triggers, NEW and OLD are read-only since the operation has already completed.', codeSnippet: "CREATE FUNCTION audit_changes()\nRETURNS TRIGGER AS $$\nBEGIN\n  IF TG_OP = 'INSERT' THEN\n    INSERT INTO audit_log(op, new_data)\n    VALUES ('INSERT', row_to_json(NEW));\n    RETURN NEW;\n  ELSIF TG_OP = 'UPDATE' THEN\n    INSERT INTO audit_log(op, old_data, new_data)\n    VALUES ('UPDATE', row_to_json(OLD), row_to_json(NEW));\n    RETURN NEW;\n  ELSIF TG_OP = 'DELETE' THEN\n    INSERT INTO audit_log(op, old_data)\n    VALUES ('DELETE', row_to_json(OLD));\n    RETURN OLD;\n  END IF;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'triggers', 'new-old', 'row-level'] },
  { id: 'pg-advanced-l2-014', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'Triggers', question: 'How do you create a BEFORE INSERT trigger function that modifies the incoming row?', options: ['Use ALTER TABLE to set default values', 'Write a trigger function that modifies the NEW record and returns NEW — in a BEFORE trigger, changes to NEW fields are reflected in the actual inserted row, allowing data validation, transformation, and automatic field population before the row is written', 'Use a CHECK constraint instead', 'Modify the INSERT statement directly'], correctAnswer: 1, explanation: 'BEFORE INSERT triggers execute before the row is written to the table. By modifying NEW.column_name, you change what gets stored. Returning NEW proceeds with the (possibly modified) insert. Returning NULL cancels the insert silently. This is commonly used for setting timestamps, normalizing data, or generating derived values.', codeSnippet: "CREATE FUNCTION set_timestamps()\nRETURNS TRIGGER AS $$\nBEGIN\n  NEW.created_at := CURRENT_TIMESTAMP;\n  NEW.updated_at := CURRENT_TIMESTAMP;\n  NEW.email := LOWER(TRIM(NEW.email));\n  NEW.slug := LOWER(REPLACE(NEW.title, ' ', '-'));\n  RETURN NEW;  -- must return NEW to proceed\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_set_timestamps\n  BEFORE INSERT ON articles\n  FOR EACH ROW\n  EXECUTE FUNCTION set_timestamps();\n\n-- Returning NULL cancels the insert:\nCREATE FUNCTION block_insert()\nRETURNS TRIGGER AS $$\nBEGIN\n  IF NEW.status = 'banned' THEN\n    RETURN NULL; -- silently skip\n  END IF;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'triggers', 'before-insert', 'modify-new'] },
  { id: 'pg-advanced-l2-015', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'Triggers', question: 'What is the TG_OP variable in a PostgreSQL trigger function?', options: ['TG_OP stores the table name', 'TG_OP stores the trigger name', 'TG_OP is a text variable that contains the operation that fired the trigger — it is set to INSERT, UPDATE, DELETE, or TRUNCATE, allowing a single trigger function to handle multiple DML event types with conditional logic', 'TG_OP stores the operation count'], correctAnswer: 2, explanation: 'TG_OP is one of several special trigger variables. Others include TG_NAME (trigger name), TG_TABLE_NAME (table name), TG_TABLE_SCHEMA (schema), TG_WHEN (BEFORE/AFTER/INSTEAD OF), TG_LEVEL (ROW/STATEMENT), TG_NARGS (number of arguments), and TG_ARGV[] (argument array). These allow writing reusable trigger functions.', codeSnippet: "CREATE FUNCTION universal_trigger()\nRETURNS TRIGGER AS $$\nBEGIN\n  RAISE NOTICE 'Trigger: %, Op: %, Table: %.%',\n    TG_NAME, TG_OP, TG_TABLE_SCHEMA, TG_TABLE_NAME;\n\n  CASE TG_OP\n    WHEN 'INSERT' THEN\n      PERFORM log_change('insert', NEW.id);\n      RETURN NEW;\n    WHEN 'UPDATE' THEN\n      PERFORM log_change('update', NEW.id);\n      RETURN NEW;\n    WHEN 'DELETE' THEN\n      PERFORM log_change('delete', OLD.id);\n      RETURN OLD;\n    WHEN 'TRUNCATE' THEN\n      PERFORM log_change('truncate', NULL);\n      RETURN NULL;\n  END CASE;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'triggers', 'tg-op', 'trigger-variables'] },
  { id: 'pg-advanced-l2-016', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'Triggers', question: 'What happens if a BEFORE trigger function returns NULL?', options: ['The operation proceeds normally', 'An error is raised', 'The database crashes', 'Returning NULL from a BEFORE row-level trigger silently cancels the operation for that row — the INSERT, UPDATE, or DELETE is skipped without raising an error, and subsequent triggers for that row are not fired'], correctAnswer: 3, explanation: 'Returning NULL from a BEFORE trigger is the mechanism for silently suppressing row operations. This is useful for soft-delete patterns, conditional filtering, or preventing certain changes. For statement-level triggers, the return value is ignored. For AFTER triggers, the return value is also ignored since the operation has already occurred.', codeSnippet: "-- Soft delete: prevent actual deletion\nCREATE FUNCTION soft_delete()\nRETURNS TRIGGER AS $$\nBEGIN\n  -- Instead of deleting, mark as deleted:\n  UPDATE users\n  SET deleted_at = CURRENT_TIMESTAMP,\n      is_active = FALSE\n  WHERE id = OLD.id;\n\n  RETURN NULL;  -- cancel the actual DELETE\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_soft_delete\n  BEFORE DELETE ON users\n  FOR EACH ROW\n  EXECUTE FUNCTION soft_delete();\n\n-- DELETE FROM users WHERE id = 1;\n-- Row is not deleted, just marked inactive", tags: ['advanced', 'triggers', 'return-null', 'cancel-operation'] },
  { id: 'pg-advanced-l2-017', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'Triggers', question: 'How do you create a trigger that only fires when specific columns are updated?', options: ['Use a CHECK constraint on the columns', 'Use CREATE TRIGGER ... AFTER UPDATE OF column1, column2 ON table — the OF clause restricts the trigger to fire only when the specified columns appear in the SET clause of the UPDATE statement, regardless of whether the values actually changed', 'Triggers always fire on all column changes', 'Use a WHERE clause in the trigger definition'], correctAnswer: 0, explanation: 'The UPDATE OF clause is an optimization that prevents the trigger from firing unnecessarily. Note that it checks if the column is in the SET clause, not whether the value actually changed. To check for actual value changes, compare OLD and NEW in the trigger function. This is particularly useful for audit triggers that only need to track changes to specific columns.', codeSnippet: "-- Only fire when price or quantity changes:\nCREATE TRIGGER trg_price_change\n  AFTER UPDATE OF price, quantity ON products\n  FOR EACH ROW\n  EXECUTE FUNCTION log_price_change();\n\n-- In the trigger function, also check actual change:\nCREATE FUNCTION log_price_change()\nRETURNS TRIGGER AS $$\nBEGIN\n  -- UPDATE OF fires even if value is same\n  -- So check for actual change:\n  IF OLD.price IS DISTINCT FROM NEW.price THEN\n    INSERT INTO price_history(product_id, old_price, new_price)\n    VALUES (NEW.id, OLD.price, NEW.price);\n  END IF;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'triggers', 'update-of', 'column-specific'] },
  { id: 'pg-advanced-l2-018', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'Triggers', question: 'What is a BEFORE UPDATE trigger that prevents certain changes?', options: ['A trigger that validates updates and can reject them by raising an exception — or selectively revert specific field changes by restoring OLD values into NEW, enforcing business rules at the database level before the row is modified', 'A constraint that blocks updates', 'A lock on the table', 'A read-only view'], correctAnswer: 1, explanation: 'BEFORE UPDATE triggers are powerful for enforcing business rules. You can raise an exception to reject the entire update, return NULL to silently cancel it, or selectively restore OLD values for specific fields to prevent certain columns from being changed. This approach is more flexible than CHECK constraints because it can reference other tables and perform complex logic.', codeSnippet: "CREATE FUNCTION protect_fields()\nRETURNS TRIGGER AS $$\nBEGIN\n  -- Prevent changing created_at:\n  IF NEW.created_at IS DISTINCT FROM OLD.created_at THEN\n    RAISE EXCEPTION 'Cannot modify created_at';\n  END IF;\n\n  -- Silently prevent changing user type:\n  NEW.user_type := OLD.user_type;\n\n  -- Auto-update updated_at:\n  NEW.updated_at := CURRENT_TIMESTAMP;\n\n  -- Prevent status rollback:\n  IF OLD.status = 'completed'\n     AND NEW.status != 'completed' THEN\n    RAISE EXCEPTION 'Cannot revert completed status';\n  END IF;\n\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_protect\n  BEFORE UPDATE ON orders\n  FOR EACH ROW\n  EXECUTE FUNCTION protect_fields();", tags: ['advanced', 'triggers', 'before-update', 'validation'] },
  { id: 'pg-advanced-l2-019', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'Triggers', question: 'How do you pass arguments to a trigger function?', options: ['Use function parameters in the CREATE FUNCTION definition', 'Use the EXECUTE FUNCTION clause with arguments — specified as string literals in the CREATE TRIGGER statement, accessible inside the trigger function via TG_NARGS (count) and TG_ARGV[] (values array), enabling reusable trigger functions', 'Arguments cannot be passed to trigger functions', 'Use SET commands before the trigger fires'], correctAnswer: 2, explanation: 'Trigger function arguments are passed as string literals in the CREATE TRIGGER statement and accessed via TG_ARGV[0], TG_ARGV[1], etc. TG_NARGS gives the count. All arguments are text type and must be cast if needed. This allows writing generic trigger functions that behave differently based on arguments, promoting code reuse.', codeSnippet: "CREATE FUNCTION generic_audit()\nRETURNS TRIGGER AS $$\nDECLARE\n  audit_table TEXT := TG_ARGV[0];\n  id_column TEXT := TG_ARGV[1];\n  id_val TEXT;\nBEGIN\n  IF TG_NARGS < 2 THEN\n    RAISE EXCEPTION 'Need audit_table and id_column args';\n  END IF;\n\n  EXECUTE format(\n    'SELECT ($1).%I::TEXT', id_column\n  ) INTO id_val USING NEW;\n\n  EXECUTE format(\n    'INSERT INTO %I(table_name, record_id, op, ts)\n     VALUES ($1, $2, $3, now())',\n    audit_table\n  ) USING TG_TABLE_NAME, id_val, TG_OP;\n\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_audit_users\n  AFTER INSERT OR UPDATE ON users\n  FOR EACH ROW\n  EXECUTE FUNCTION generic_audit('audit_log', 'id');", tags: ['advanced', 'triggers', 'tg-argv', 'trigger-arguments'] },
  { id: 'pg-advanced-l2-020', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'Triggers', question: 'What is a conditional trigger using the WHEN clause?', options: ['A trigger with a WHERE clause in its SQL', 'A trigger that uses IF statements internally', 'A trigger with WHEN (condition) in the CREATE TRIGGER statement — the condition is evaluated before the trigger function is called, and can reference NEW and OLD to avoid invoking the function unnecessarily, improving performance', 'A trigger that runs only on weekdays'], correctAnswer: 3, explanation: 'The WHEN clause is evaluated by the trigger mechanism before calling the function, which is more efficient than checking the condition inside the function. For BEFORE triggers, WHEN can reference NEW and OLD. The condition must be a boolean expression and cannot contain subqueries. This is an optimization — functionally equivalent to checking at the start of the trigger function, but avoids the function call overhead.', codeSnippet: "-- Only fire when status actually changes:\nCREATE TRIGGER trg_status_change\n  AFTER UPDATE ON orders\n  FOR EACH ROW\n  WHEN (OLD.status IS DISTINCT FROM NEW.status)\n  EXECUTE FUNCTION notify_status_change();\n\n-- Only fire for high-value inserts:\nCREATE TRIGGER trg_high_value\n  AFTER INSERT ON orders\n  FOR EACH ROW\n  WHEN (NEW.total > 10000)\n  EXECUTE FUNCTION alert_high_value();\n\n-- Only fire for non-system updates:\nCREATE TRIGGER trg_user_update\n  BEFORE UPDATE ON settings\n  FOR EACH ROW\n  WHEN (NEW.modified_by != 'system')\n  EXECUTE FUNCTION validate_update();", tags: ['advanced', 'triggers', 'when-clause', 'conditional-trigger'] },
  { id: 'pg-advanced-l2-021', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'Triggers', question: 'What is the difference between row-level and statement-level triggers?', options: ['Row-level triggers run once per affected row (FOR EACH ROW), while statement-level triggers run once per SQL statement (FOR EACH STATEMENT) — row-level triggers have access to NEW/OLD records, statement-level triggers do not have access to individual row data', 'They are identical', 'Row-level runs first, statement-level runs last', 'Statement-level triggers are faster'], correctAnswer: 0, explanation: 'Row-level triggers (FOR EACH ROW) execute once for each row affected and can access/modify individual rows via NEW/OLD. Statement-level triggers (FOR EACH STATEMENT) execute once regardless of how many rows are affected and cannot access individual rows. Statement-level triggers are useful for logging that an operation occurred or for post-operation cleanup that does not need row-level detail.', codeSnippet: "-- Row-level: runs for each inserted row\nCREATE TRIGGER trg_row\n  AFTER INSERT ON orders\n  FOR EACH ROW\n  EXECUTE FUNCTION process_order();\n\n-- Statement-level: runs once per INSERT statement\nCREATE TRIGGER trg_stmt\n  AFTER INSERT ON orders\n  FOR EACH STATEMENT\n  EXECUTE FUNCTION log_bulk_insert();\n\n-- INSERT INTO orders VALUES (1),(2),(3);\n-- trg_row fires 3 times (once per row)\n-- trg_stmt fires 1 time (once for statement)\n\n-- Statement-level function (no NEW/OLD):\nCREATE FUNCTION log_bulk_insert()\nRETURNS TRIGGER AS $$\nBEGIN\n  INSERT INTO operation_log(table_name, operation, ts)\n  VALUES (TG_TABLE_NAME, TG_OP, now());\n  RETURN NULL; -- return value ignored\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'triggers', 'row-level', 'statement-level'] },
  { id: 'pg-advanced-l2-022', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'Triggers', question: 'How do you create a trigger that maintains a summary table?', options: ['Use a scheduled job to recalculate', 'Use a materialized view instead', 'Create a trigger function that updates the summary table on each DML operation — using NEW and OLD values to incrementally adjust aggregated counts, sums, and averages without recalculating from scratch', 'Summary tables cannot be maintained automatically'], correctAnswer: 1, explanation: 'Triggers for summary maintenance perform incremental updates: on INSERT, add to the summary; on DELETE, subtract; on UPDATE, adjust the difference. This is more efficient than recalculating aggregates from the base table. The trigger function handles all three operations using TG_OP. This pattern is essential for denormalization in high-read workloads.', codeSnippet: "CREATE FUNCTION update_order_summary()\nRETURNS TRIGGER AS $$\nBEGIN\n  IF TG_OP = 'INSERT' THEN\n    INSERT INTO order_summary(customer_id, order_count, total_amount)\n    VALUES (NEW.customer_id, 1, NEW.amount)\n    ON CONFLICT (customer_id) DO UPDATE\n    SET order_count = order_summary.order_count + 1,\n        total_amount = order_summary.total_amount + NEW.amount;\n  ELSIF TG_OP = 'DELETE' THEN\n    UPDATE order_summary\n    SET order_count = order_count - 1,\n        total_amount = total_amount - OLD.amount\n    WHERE customer_id = OLD.customer_id;\n  ELSIF TG_OP = 'UPDATE' THEN\n    UPDATE order_summary\n    SET total_amount = total_amount - OLD.amount + NEW.amount\n    WHERE customer_id = OLD.customer_id;\n  END IF;\n  RETURN NULL; -- AFTER trigger\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'triggers', 'summary-table', 'denormalization'] },
  { id: 'pg-advanced-l2-023', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How does the EXECUTE command work for dynamic SQL in PL/pgSQL?', options: ['EXECUTE runs shell commands from PostgreSQL', 'EXECUTE is an alias for SELECT', 'EXECUTE runs a dynamically constructed SQL string — allowing table names, column names, and SQL structures to be determined at runtime, with USING clause for safe parameter binding to prevent SQL injection', 'EXECUTE runs stored procedures'], correctAnswer: 2, explanation: 'EXECUTE is essential when SQL statements need to be built dynamically (e.g., variable table names). The USING clause provides parameterized values ($1, $2) that are safely bound, preventing SQL injection for data values. For identifiers (table/column names), use format() with %I (identifier quoting) or quote_ident(). Never concatenate user input directly into dynamic SQL.', codeSnippet: "CREATE FUNCTION dynamic_count(table_name TEXT, where_col TEXT, where_val TEXT)\nRETURNS BIGINT AS $$\nDECLARE\n  result BIGINT;\nBEGIN\n  -- Safe: %I quotes identifiers, $1 binds values\n  EXECUTE format(\n    'SELECT COUNT(*) FROM %I WHERE %I = $1',\n    table_name, where_col\n  )\n  INTO result\n  USING where_val;\n\n  RETURN result;\nEND;\n$$ LANGUAGE plpgsql;\n\nSELECT dynamic_count('users', 'status', 'active');\n-- Generates: SELECT COUNT(*) FROM users WHERE status = 'active'", tags: ['advanced', 'plpgsql', 'execute', 'dynamic-sql'] },
  { id: 'pg-advanced-l2-024', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'What is the FOUND variable in PL/pgSQL?', options: ['FOUND indicates whether the most recent SQL statement affected or returned at least one row — it is set after SELECT INTO, INSERT, UPDATE, DELETE, PERFORM, and FOR/FOREACH loops, providing a lightweight way to check operation results', 'FOUND stores the number of rows found', 'FOUND contains the query result', 'FOUND is a function that searches tables'], correctAnswer: 3, explanation: 'FOUND is a boolean variable automatically set by PL/pgSQL after each SQL command. After SELECT INTO, it is true if a row was returned. After INSERT/UPDATE/DELETE, it is true if at least one row was affected. After a FOR loop, it is true if the loop iterated at least once. FOUND is more convenient than GET DIAGNOSTICS for simple existence checks.', codeSnippet: "CREATE FUNCTION get_user_email(user_id INTEGER)\nRETURNS TEXT AS $$\nDECLARE\n  email TEXT;\nBEGIN\n  SELECT u.email INTO email\n  FROM users u WHERE u.id = user_id;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'User % not found', user_id;\n  END IF;\n\n  RETURN email;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Also works with DML:\nCREATE FUNCTION deactivate_user(user_id INTEGER)\nRETURNS BOOLEAN AS $$\nBEGIN\n  UPDATE users SET active = FALSE WHERE id = user_id;\n  RETURN FOUND; -- true if row was updated\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'plpgsql', 'found', 'existence-check'] },
  { id: 'pg-advanced-l2-025', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you use cursors in PL/pgSQL?', options: ['Cursors are declared with CURSOR FOR query, opened with OPEN, read row by row with FETCH, and closed with CLOSE — they allow processing large result sets one row at a time without loading everything into memory', 'Cursors are the same as temporary tables', 'Use SELECT INTO for cursor operations', 'Cursors are not supported in PL/pgSQL'], correctAnswer: 0, explanation: 'Cursors provide row-by-row access to query results. They are useful for processing very large result sets where loading all rows into memory is impractical. Cursor variables can be passed between functions using refcursor type. However, FOR loops over queries are generally preferred for simplicity unless you need explicit cursor control (e.g., fetching in chunks or passing cursors between functions).', codeSnippet: "CREATE FUNCTION process_large_table()\nRETURNS INTEGER AS $$\nDECLARE\n  cur CURSOR FOR\n    SELECT id, data FROM large_table\n    ORDER BY id;\n  rec RECORD;\n  processed INTEGER := 0;\nBEGIN\n  OPEN cur;\n  LOOP\n    FETCH cur INTO rec;\n    EXIT WHEN NOT FOUND;\n\n    -- Process row:\n    UPDATE large_table\n    SET processed = TRUE\n    WHERE id = rec.id;\n\n    processed := processed + 1;\n  END LOOP;\n  CLOSE cur;\n  RETURN processed;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Simpler: FOR loop auto-manages cursor:\nFOR rec IN SELECT * FROM large_table LOOP\n  -- process rec\nEND LOOP;", tags: ['advanced', 'plpgsql', 'cursors', 'fetch'] },
  { id: 'pg-advanced-l2-026', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'pg_trgm', question: 'What is the pg_trgm extension in PostgreSQL?', options: ['A trigonometric functions library', 'A data compression tool', 'pg_trgm provides trigram-based text similarity functions and operators — it splits text into groups of three consecutive characters to measure how similar two strings are, enabling fuzzy matching, typo-tolerant search, and efficient LIKE/ILIKE queries via GIN or GiST indexes', 'A trigger management tool'], correctAnswer: 1, explanation: 'pg_trgm (trigram) decomposes strings into sequences of three consecutive characters. "hello" becomes {"  h"," he","hel","ell","llo","lo "} (with padding). Similarity is measured by comparing trigram sets using Jaccard index. This is extremely effective for fuzzy text search, autocomplete, and spell correction. GIN/GiST indexes on trigrams also accelerate LIKE and ILIKE pattern matching.', codeSnippet: "CREATE EXTENSION pg_trgm;\n\n-- Show trigrams:\nSELECT show_trgm('hello');\n-- {\"  h\",\" he\",hel,ell,llo,\"lo \",\"o  \"}\n\n-- Similarity (0.0 to 1.0):\nSELECT similarity('hello', 'helo');  -- 0.5\nSELECT similarity('hello', 'world'); -- 0.0\n\n-- Similarity operator:\nSELECT 'hello' % 'helo'; -- true (above threshold)\n\n-- Set threshold:\nSET pg_trgm.similarity_threshold = 0.3;", tags: ['advanced', 'pg-trgm', 'trigram', 'similarity'] },
  { id: 'pg-advanced-l2-027', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'pg_trgm', question: 'How do you create an index for trigram similarity search?', options: ['Use a B-tree index on the text column', 'Use a hash index on the text column', 'Create a GIN or GiST index using the gin_trgm_ops or gist_trgm_ops operator class — these indexes support the % (similarity), <% (word similarity), and <<% (strict word similarity) operators, plus LIKE and ILIKE pattern matching', 'Trigram searches cannot be indexed'], correctAnswer: 2, explanation: 'GIN indexes with gin_trgm_ops are generally preferred for trigram searches — they are faster for lookups but slower to build and update. GiST indexes with gist_trgm_ops are lossy but support KNN distance ordering (ORDER BY column <-> pattern). Both index types also accelerate regular LIKE/ILIKE queries, which normally require sequential scans.', codeSnippet: "-- GIN index (faster lookups):\nCREATE INDEX idx_name_trgm_gin\n  ON users USING gin (name gin_trgm_ops);\n\n-- GiST index (supports ORDER BY distance):\nCREATE INDEX idx_name_trgm_gist\n  ON users USING gist (name gist_trgm_ops);\n\n-- Similarity search (uses GIN or GiST):\nSELECT name, similarity(name, 'Jonh') AS sim\nFROM users\nWHERE name % 'Jonh'\nORDER BY sim DESC;\n\n-- KNN search (requires GiST):\nSELECT name, name <-> 'Jonh' AS dist\nFROM users\nORDER BY name <-> 'Jonh'\nLIMIT 10;\n\n-- LIKE now uses the index too:\nSELECT * FROM users\nWHERE name LIKE '%john%';", tags: ['advanced', 'pg-trgm', 'gin-index', 'gist-index', 'fuzzy-search'] },
  { id: 'pg-advanced-l2-028', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'pg_trgm', question: 'What is the difference between similarity() and word_similarity() in pg_trgm?', options: ['They are identical functions', 'similarity() is faster than word_similarity()', 'similarity() compares whole strings by their trigram sets, while word_similarity() finds the best match of the first string within any substring of the second — useful for matching a search term against longer text where the target may be embedded in a larger string', 'word_similarity() only works with single words'], correctAnswer: 3, explanation: 'similarity() computes the Jaccard similarity between the trigram sets of two complete strings. word_similarity() (added in PostgreSQL 9.6) finds the substring in the second string that has the highest similarity to the first string. This is ideal for searching a short query term within longer text. strict_word_similarity() (PG 13+) is even stricter about word boundaries.', codeSnippet: "SELECT\n  similarity('search', 'full text search engine') AS sim,\n  word_similarity('search', 'full text search engine') AS wsim;\n-- sim:  ~0.12 (whole string comparison)\n-- wsim: ~0.6  (finds 'search' substring)\n\n-- Operators:\n-- %   uses similarity()\n-- <%  uses word_similarity()\n-- <<% uses strict_word_similarity()\n\nSELECT title\nFROM articles\nWHERE 'databse' <% title  -- typo-tolerant\nORDER BY 'databse' <<-> title\nLIMIT 10;\n\n-- Distance operators:\n-- <->  similarity distance\n-- <->> word_similarity distance\n-- <<<-> strict word similarity distance", tags: ['advanced', 'pg-trgm', 'word-similarity', 'substring-match'] },
  { id: 'pg-advanced-l2-029', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'pg_trgm', question: 'How do you use pg_trgm to accelerate LIKE and ILIKE queries?', options: ['LIKE queries cannot use indexes', 'Add a B-tree index with a special collation', 'Simply create a GIN index with gin_trgm_ops on the column — PostgreSQL will automatically use the trigram index for LIKE, ILIKE, and regex (~) patterns, even for patterns with leading wildcards like %substring% that B-tree indexes cannot handle', 'Convert LIKE to = with preprocessing'], correctAnswer: 0, explanation: 'Without pg_trgm, LIKE with a leading wildcard (e.g., %text%) requires a full table scan because B-tree indexes only help with prefix patterns. A GIN trigram index extracts trigrams from the pattern and uses the index to find rows containing those trigrams, dramatically speeding up arbitrary substring searches. This is one of the most practical uses of pg_trgm.', codeSnippet: "-- Without pg_trgm, this is a sequential scan:\nEXPLAIN SELECT * FROM products\nWHERE name ILIKE '%phone%';\n-- Seq Scan on products\n\n-- Add trigram index:\nCREATE INDEX idx_product_name_trgm\n  ON products USING gin (name gin_trgm_ops);\n\n-- Now it uses the index:\nEXPLAIN SELECT * FROM products\nWHERE name ILIKE '%phone%';\n-- Bitmap Index Scan on idx_product_name_trgm\n\n-- Also works with regex:\nSELECT * FROM products\nWHERE name ~ 'i[Pp]hone';\n-- Uses the trigram index too!", tags: ['advanced', 'pg-trgm', 'like-optimization', 'ilike-index'] },
  { id: 'pg-advanced-l2-030', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'pg_trgm', question: 'How do you tune the similarity threshold in pg_trgm?', options: ['Modify the postgresql.conf file and restart', 'Use SET pg_trgm.similarity_threshold — this session-level setting (default 0.3) controls the minimum similarity score required for the % operator to return true, allowing you to adjust fuzzy match strictness per session or transaction', 'The threshold is fixed at 0.5', 'Use ALTER EXTENSION to change it'], correctAnswer: 1, explanation: 'The similarity threshold determines how close a match must be for the % operator to return true. Lower values (e.g., 0.1) produce more matches but with lower quality. Higher values (e.g., 0.8) require closer matches. The default 0.3 is a reasonable starting point. There are also separate thresholds: pg_trgm.word_similarity_threshold and pg_trgm.strict_word_similarity_threshold for the <% and <<% operators.', codeSnippet: "-- Check current threshold:\nSHOW pg_trgm.similarity_threshold; -- 0.3\n\n-- More lenient (more results, lower quality):\nSET pg_trgm.similarity_threshold = 0.1;\nSELECT name FROM users WHERE name % 'Jhon';\n-- Returns many approximate matches\n\n-- More strict (fewer results, higher quality):\nSET pg_trgm.similarity_threshold = 0.6;\nSELECT name FROM users WHERE name % 'Jhon';\n-- Only very close matches\n\n-- Word similarity threshold:\nSET pg_trgm.word_similarity_threshold = 0.4;\nSELECT title FROM articles\nWHERE 'database' <% title;", tags: ['advanced', 'pg-trgm', 'threshold', 'tuning'] },
  { id: 'pg-advanced-l2-031', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'postgres_fdw', question: 'What is postgres_fdw in PostgreSQL?', options: ['A file download utility for PostgreSQL', 'A data format converter', 'postgres_fdw is a foreign data wrapper extension that allows querying tables on remote PostgreSQL servers as if they were local — it creates foreign tables that proxy SELECT, INSERT, UPDATE, and DELETE operations to the remote database transparently', 'A database firewall module'], correctAnswer: 2, explanation: 'postgres_fdw implements the SQL/MED (Management of External Data) standard. It establishes connections to remote PostgreSQL servers and maps remote tables to local foreign table definitions. Queries against foreign tables are translated and pushed to the remote server, with WHERE clauses, joins, sorts, and aggregates pushed down when possible for performance. It supports transactions across servers.', codeSnippet: "-- Install the extension:\nCREATE EXTENSION postgres_fdw;\n\n-- Create a foreign server:\nCREATE SERVER remote_db\n  FOREIGN DATA WRAPPER postgres_fdw\n  OPTIONS (\n    host 'remote-host.example.com',\n    port '5432',\n    dbname 'production'\n  );\n\n-- Create user mapping:\nCREATE USER MAPPING FOR current_user\n  SERVER remote_db\n  OPTIONS (\n    user 'remote_user',\n    password 'secret'\n  );\n\n-- Create foreign table:\nCREATE FOREIGN TABLE remote_users (\n  id INTEGER,\n  name TEXT,\n  email TEXT\n) SERVER remote_db\n  OPTIONS (schema_name 'public', table_name 'users');", tags: ['advanced', 'postgres-fdw', 'foreign-data-wrapper', 'remote-tables'] },
  { id: 'pg-advanced-l2-032', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'postgres_fdw', question: 'How do you import a remote schema using postgres_fdw?', options: ['Use pg_dump and pg_restore', 'Use COPY command to transfer schema', 'Use IMPORT FOREIGN SCHEMA remote_schema FROM SERVER server_name INTO local_schema — which automatically creates foreign table definitions for all (or selected) tables in the remote schema, avoiding manual CREATE FOREIGN TABLE statements', 'Use CREATE TABLE AS SELECT from the remote'], correctAnswer: 3, explanation: 'IMPORT FOREIGN SCHEMA automates creating foreign tables by reading the remote catalog. You can import all tables or limit to specific ones with LIMIT TO or exclude some with EXCEPT. The imported foreign tables match the remote table structures. This is much more convenient than manually defining each foreign table, especially for schemas with many tables.', codeSnippet: "-- Import all tables from remote public schema:\nIMPORT FOREIGN SCHEMA public\n  FROM SERVER remote_db\n  INTO local_foreign;\n\n-- Import only specific tables:\nIMPORT FOREIGN SCHEMA public\n  LIMIT TO (users, orders, products)\n  FROM SERVER remote_db\n  INTO local_foreign;\n\n-- Exclude certain tables:\nIMPORT FOREIGN SCHEMA public\n  EXCEPT (temp_data, logs)\n  FROM SERVER remote_db\n  INTO local_foreign;\n\n-- Now query remote tables locally:\nSELECT * FROM local_foreign.users\nWHERE created_at > '2024-01-01';", tags: ['advanced', 'postgres-fdw', 'import-foreign-schema', 'automation'] },
  { id: 'pg-advanced-l2-033', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'postgres_fdw', question: 'What is query pushdown in postgres_fdw?', options: ['Pushing queries to a message queue', 'Sending queries to a lower-priority thread', 'Query pushdown means postgres_fdw sends as much of the query as possible to the remote server for execution — including WHERE filters, JOIN operations, sorts, aggregates, and LIMIT clauses — instead of fetching all rows and processing them locally', 'Caching query results locally'], correctAnswer: 0, explanation: 'Pushdown optimization is critical for performance. Without it, the entire remote table would be transferred. postgres_fdw can push down WHERE conditions, ORDER BY, LIMIT, aggregate functions, joins between tables on the same remote server, and UPDATE/DELETE with simple WHERE clauses. Use EXPLAIN VERBOSE to see what gets pushed down. Some expressions (like custom functions) may not be pushed down.', codeSnippet: "-- Check what gets pushed down:\nEXPLAIN VERBOSE\nSELECT name, COUNT(*)\nFROM remote_orders\nWHERE status = 'active'\nGROUP BY name\nHAVING COUNT(*) > 5\nORDER BY COUNT(*) DESC\nLIMIT 10;\n\n-- Output shows Remote SQL:\n-- Foreign Scan\n--   Remote SQL: SELECT name, count(*)\n--     FROM public.orders\n--     WHERE (status = 'active')\n--     GROUP BY name HAVING (count(*) > 5)\n--     ORDER BY count(*) DESC LIMIT 10\n\n-- Everything was pushed to remote server!", tags: ['advanced', 'postgres-fdw', 'pushdown', 'performance'] },
  { id: 'pg-advanced-l2-034', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'postgres_fdw', question: 'How do you configure connection pooling and caching for postgres_fdw?', options: ['postgres_fdw automatically uses PgBouncer', 'Use the fdw_connection_pool extension', 'Use the fetch_size option to control how many rows are retrieved per batch, and keep_connections to control whether connections to the remote server are cached between transactions for the same session', 'Connection management is not configurable'], correctAnswer: 1, explanation: 'fetch_size (default 100) controls the number of rows fetched in each batch from the remote server — larger values reduce round trips but use more memory. keep_connections (default on) caches connections for reuse within a session. You can also set use_remote_estimate to let the planner use remote statistics for better query plans. These options significantly impact performance.', codeSnippet: "-- Set fetch size for a foreign table:\nALTER FOREIGN TABLE remote_orders\n  OPTIONS (SET fetch_size '1000');\n\n-- Set on the server level:\nALTER SERVER remote_db\n  OPTIONS (ADD fetch_size '500');\n\n-- Keep connections between transactions:\nALTER SERVER remote_db\n  OPTIONS (ADD keep_connections 'on');\n\n-- Use remote ANALYZE statistics:\nALTER SERVER remote_db\n  OPTIONS (ADD use_remote_estimate 'true');\n\n-- View active foreign server connections:\nSELECT * FROM postgres_fdw_get_connections();\n\n-- Disconnect cached connections:\nSELECT postgres_fdw_disconnect('remote_db');", tags: ['advanced', 'postgres-fdw', 'fetch-size', 'connection-caching'] },
  { id: 'pg-advanced-l2-035', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'postgres_fdw', question: 'Can you write to foreign tables using postgres_fdw?', options: ['Foreign tables are always read-only', 'Only INSERT is supported on foreign tables', 'Yes — postgres_fdw supports INSERT, UPDATE, and DELETE on foreign tables, and the modifications are executed on the remote server as part of a distributed transaction that commits or rolls back together with the local transaction', 'Only with a special writable_fdw extension'], correctAnswer: 2, explanation: 'postgres_fdw supports full DML on foreign tables since PostgreSQL 9.3. Write operations are forwarded to the remote server. PostgreSQL uses a two-phase commit-like protocol to coordinate transactions. The updatable option on foreign tables can be set to false to prevent writes. COPY, INSERT...ON CONFLICT, and RETURNING clauses are also supported.', codeSnippet: "-- Insert into remote table:\nINSERT INTO remote_users (name, email)\nVALUES ('Alice', 'alice@example.com');\n\n-- Update remote rows:\nUPDATE remote_users\nSET email = 'newemail@example.com'\nWHERE name = 'Alice';\n\n-- Delete from remote:\nDELETE FROM remote_users\nWHERE last_login < '2023-01-01';\n\n-- Make a foreign table read-only:\nALTER FOREIGN TABLE remote_users\n  OPTIONS (ADD updatable 'false');\n\n-- RETURNING works too:\nINSERT INTO remote_users (name, email)\nVALUES ('Bob', 'bob@example.com')\nRETURNING id;", tags: ['advanced', 'postgres-fdw', 'writable', 'insert-update-delete'] },
  { id: 'pg-advanced-l2-036', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'Materialized Views', question: 'What does REFRESH MATERIALIZED VIEW CONCURRENTLY do?', options: ['It refreshes the view in a background thread', 'It refreshes the view faster using parallel workers', 'It refreshes the materialized view without locking it for reads — a new version of the data is computed and then swapped in atomically, allowing SELECT queries to continue using the old data during the refresh process', 'It refreshes only changed rows'], correctAnswer: 3, explanation: 'REFRESH MATERIALIZED VIEW CONCURRENTLY avoids taking an exclusive lock that would block reads during the refresh. Instead, it computes the new data alongside the old data and performs a diff-based update. This requires a UNIQUE index on the materialized view. The tradeoff is that CONCURRENTLY is slower than a regular refresh because it must compare old and new data, but it does not block concurrent readers.', codeSnippet: "-- Create materialized view with unique index:\nCREATE MATERIALIZED VIEW mv_sales_summary AS\nSELECT\n  product_id,\n  DATE_TRUNC('month', sale_date) AS month,\n  SUM(amount) AS total,\n  COUNT(*) AS num_sales\nFROM sales\nGROUP BY product_id, DATE_TRUNC('month', sale_date);\n\n-- Required for CONCURRENTLY:\nCREATE UNIQUE INDEX ON mv_sales_summary\n  (product_id, month);\n\n-- Non-concurrent (blocks reads):\nREFRESH MATERIALIZED VIEW mv_sales_summary;\n\n-- Concurrent (allows reads during refresh):\nREFRESH MATERIALIZED VIEW CONCURRENTLY\n  mv_sales_summary;", tags: ['advanced', 'materialized-views', 'refresh-concurrently', 'non-blocking'] },
  { id: 'pg-advanced-l2-037', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'Materialized Views', question: 'What is required to use REFRESH MATERIALIZED VIEW CONCURRENTLY?', options: ['The view must have no joins', 'The view must be owned by a superuser', 'The view must have a unique index on it', 'The materialized view must have at least one UNIQUE index that covers all rows (no NULLs in the indexed columns) — this is needed to identify which rows changed between the old and new data during the concurrent refresh'], correctAnswer: 0, explanation: 'The UNIQUE index requirement exists because CONCURRENTLY refresh works by computing the new data set, comparing it with the old data, and applying the differences (inserts, updates, deletes). Without a unique index, PostgreSQL cannot reliably match old rows to new rows. The indexed columns must not contain NULLs. If no unique index exists, you get an error when attempting CONCURRENTLY.', codeSnippet: "-- This will fail without a unique index:\nREFRESH MATERIALIZED VIEW CONCURRENTLY mv_report;\n-- ERROR: cannot refresh concurrently without\n-- at least one unique index\n\n-- Add unique index:\nCREATE UNIQUE INDEX ON mv_report (id);\n\n-- Now it works:\nREFRESH MATERIALIZED VIEW CONCURRENTLY mv_report;\n\n-- For composite keys:\nCREATE UNIQUE INDEX ON mv_monthly_stats\n  (product_id, month);\n\n-- NULLs in unique columns prevent CONCURRENTLY:\n-- Ensure indexed columns are NOT NULL in the view query", tags: ['advanced', 'materialized-views', 'unique-index', 'concurrently-requirement'] },
  { id: 'pg-advanced-l2-038', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'Materialized Views', question: 'How do you automate materialized view refreshes in PostgreSQL?', options: ['PostgreSQL automatically refreshes materialized views', 'Use pg_cron extension or an external scheduler to periodically call REFRESH MATERIALIZED VIEW — since PostgreSQL does not support automatic or incremental refresh of materialized views, manual scheduling is the standard approach', 'Use a trigger on the base tables', 'Use the AUTO REFRESH option in CREATE MATERIALIZED VIEW'], correctAnswer: 1, explanation: 'PostgreSQL materialized views are not automatically refreshed when base data changes. The most common approach is using pg_cron (a PostgreSQL extension for scheduling) or an external scheduler (cron, systemd timer, application scheduler). For near-real-time updates, you can use triggers on base tables to call REFRESH, though this adds overhead to each DML operation.', codeSnippet: "-- Using pg_cron extension:\nCREATE EXTENSION pg_cron;\n\n-- Refresh every hour:\nSELECT cron.schedule(\n  'refresh-sales-mv',\n  '0 * * * *',  -- every hour\n  'REFRESH MATERIALIZED VIEW CONCURRENTLY mv_sales'\n);\n\n-- Refresh daily at 3 AM:\nSELECT cron.schedule(\n  'refresh-daily-mv',\n  '0 3 * * *',\n  'REFRESH MATERIALIZED VIEW CONCURRENTLY mv_daily'\n);\n\n-- List scheduled jobs:\nSELECT * FROM cron.job;\n\n-- Remove a scheduled refresh:\nSELECT cron.unschedule('refresh-sales-mv');", tags: ['advanced', 'materialized-views', 'pg-cron', 'scheduling'] },
  { id: 'pg-advanced-l2-039', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'Materialized Views', question: 'What is the WITH NO DATA option when creating a materialized view?', options: ['It creates a view with no columns', 'It creates an empty temporary view', 'CREATE MATERIALIZED VIEW ... WITH NO DATA creates the view definition without populating it — the view exists but contains no rows and cannot be queried until REFRESH MATERIALIZED VIEW is called, useful for deferring the initial expensive data load', 'It creates a view that ignores NULL values'], correctAnswer: 2, explanation: 'WITH NO DATA is useful when you want to define the materialized view structure upfront but populate it later (e.g., during off-peak hours). Querying an unpopulated materialized view raises an error. You can check if a materialized view is populated by querying pg_matviews.ispopulated. This is also useful in migration scripts where you define views first and populate them in a separate step.', codeSnippet: "-- Create without data:\nCREATE MATERIALIZED VIEW mv_analytics\nAS SELECT\n  user_id,\n  COUNT(*) AS events,\n  MAX(created_at) AS last_event\nFROM event_log\nGROUP BY user_id\nWITH NO DATA;\n\n-- Cannot query yet:\nSELECT * FROM mv_analytics;\n-- ERROR: materialized view has not been populated\n\n-- Check if populated:\nSELECT matviewname, ispopulated\nFROM pg_matviews\nWHERE matviewname = 'mv_analytics';\n-- ispopulated = false\n\n-- Populate it:\nREFRESH MATERIALIZED VIEW mv_analytics;\n-- Now queries work", tags: ['advanced', 'materialized-views', 'with-no-data', 'deferred-population'] },
  { id: 'pg-advanced-l2-040', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'LISTEN/NOTIFY', question: 'What is the LISTEN/NOTIFY system in PostgreSQL?', options: ['A message queue replacement like RabbitMQ', 'A monitoring and alerting system', 'An inter-process communication mechanism — LISTEN registers interest in a named channel, and NOTIFY sends a message (with optional payload) to all sessions listening on that channel, enabling real-time event notification between database sessions', 'A replication protocol between servers'], correctAnswer: 3, explanation: 'LISTEN/NOTIFY is a lightweight pub/sub system built into PostgreSQL. Sessions register interest with LISTEN channel_name and receive messages sent with NOTIFY channel_name. Notifications are transactional — they are only delivered when the sending transaction commits. The payload can carry up to 8000 bytes of text. This is commonly used for cache invalidation, real-time updates, and job queue notifications.', codeSnippet: "-- Session 1: Listen for events\nLISTEN order_events;\n\n-- Session 2: Send notification\nNOTIFY order_events, 'new_order:12345';\n\n-- Or use pg_notify function:\nSELECT pg_notify('order_events',\n  json_build_object(\n    'action', 'created',\n    'order_id', 12345,\n    'total', 99.99\n  )::TEXT\n);\n\n-- Session 1 receives:\n-- Asynchronous notification \"order_events\"\n--   with payload \"new_order:12345\"\n--   from server process PID 1234\n\n-- Stop listening:\nUNLISTEN order_events;\nUNLISTEN *; -- all channels", tags: ['advanced', 'listen-notify', 'pubsub', 'real-time'] },
  { id: 'pg-advanced-l2-041', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'LISTEN/NOTIFY', question: 'How does NOTIFY interact with transactions?', options: ['NOTIFY sends messages immediately regardless of transaction state', 'NOTIFY messages are sent before the transaction commits', 'NOTIFY messages are only delivered when the sending transaction commits — if the transaction rolls back, the notifications are discarded, ensuring that listeners only receive notifications for changes that actually persisted', 'NOTIFY requires autocommit mode'], correctAnswer: 0, explanation: 'Transactional delivery is a key feature of LISTEN/NOTIFY. Notifications are queued during the transaction and only dispatched upon COMMIT. This prevents listeners from reacting to changes that might be rolled back. If the same notification (same channel and payload) is sent multiple times in a single transaction, PostgreSQL coalesces them into one delivery for efficiency.', codeSnippet: "-- Transactional behavior:\nBEGIN;\n  INSERT INTO orders(id, total) VALUES (1, 100);\n  NOTIFY new_orders, 'order_id=1';\n  -- Notification queued but not sent yet\n\n  INSERT INTO orders(id, total) VALUES (2, 200);\n  NOTIFY new_orders, 'order_id=2';\nCOMMIT;\n-- Both notifications delivered now\n\n-- Rollback discards notifications:\nBEGIN;\n  INSERT INTO orders(id, total) VALUES (3, 300);\n  NOTIFY new_orders, 'order_id=3';\nROLLBACK;\n-- Notification discarded, never sent\n\n-- Duplicate coalescing:\nBEGIN;\n  NOTIFY ch, 'same payload';\n  NOTIFY ch, 'same payload';\nCOMMIT;\n-- Only ONE notification delivered", tags: ['advanced', 'listen-notify', 'transactions', 'delivery-guarantees'] },
  { id: 'pg-advanced-l2-042', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'LISTEN/NOTIFY', question: 'How do you use NOTIFY with triggers for real-time event notifications?', options: ['Triggers cannot use NOTIFY', 'Use pg_notify() inside a trigger function to send notifications when data changes — combining TG_OP and row data into the payload allows external applications listening on the channel to react to INSERT, UPDATE, and DELETE events in real time', 'NOTIFY only works from client applications', 'Use a separate polling mechanism'], correctAnswer: 1, explanation: 'Trigger-based NOTIFY is a common pattern for real-time event-driven architectures. The trigger function constructs a JSON payload with the operation type and relevant row data, then sends it via pg_notify(). Since triggers are transactional, the notification is only sent when the triggering transaction commits. Applications (Node.js, Python, etc.) listen on the channel and react accordingly.', codeSnippet: "CREATE FUNCTION notify_changes()\nRETURNS TRIGGER AS $$\nDECLARE\n  payload JSON;\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    payload = json_build_object(\n      'op', TG_OP, 'id', OLD.id);\n  ELSE\n    payload = json_build_object(\n      'op', TG_OP, 'id', NEW.id,\n      'data', row_to_json(NEW));\n  END IF;\n\n  PERFORM pg_notify(\n    'table_' || TG_TABLE_NAME, payload::TEXT\n  );\n\n  RETURN COALESCE(NEW, OLD);\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_notify\n  AFTER INSERT OR UPDATE OR DELETE ON orders\n  FOR EACH ROW\n  EXECUTE FUNCTION notify_changes();\n\n-- App listens: LISTEN table_orders;", tags: ['advanced', 'listen-notify', 'triggers', 'real-time-events'] },
  { id: 'pg-advanced-l2-043', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'LISTEN/NOTIFY', question: 'What are the limitations of PostgreSQL LISTEN/NOTIFY?', options: ['There are no limitations', 'It only works on localhost', 'Payload is limited to 8000 bytes, notifications are not persisted (lost if listener is disconnected), there is no message acknowledgment, and the notification queue has a fixed memory limit (default 65536 pending notifications) that can cause NOTIFY to fail', 'It only supports one listener per channel'], correctAnswer: 2, explanation: 'LISTEN/NOTIFY is lightweight but not a full message queue. Key limitations: 8000 byte payload limit (use a reference ID and look up details separately for larger data), no persistence (if the listener disconnects, messages are lost), no delivery guarantees, and queue size limits. For guaranteed delivery, combine with a job queue table. The notification queue size is controlled by max_notify_queue_pages.', codeSnippet: "-- Payload limit:\nSELECT pg_notify('ch', repeat('x', 8000)); -- OK\nSELECT pg_notify('ch', repeat('x', 8001));\n-- ERROR: payload string too long\n\n-- Workaround: send reference, not full data:\nCREATE FUNCTION notify_with_ref()\nRETURNS TRIGGER AS $$\nBEGIN\n  -- Just send the ID, not full row:\n  PERFORM pg_notify('changes',\n    json_build_object(\n      'table', TG_TABLE_NAME,\n      'op', TG_OP,\n      'id', NEW.id\n    )::TEXT\n  );\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Monitor queue usage:\nSELECT * FROM pg_notification_queue_usage();", tags: ['advanced', 'listen-notify', 'limitations', 'payload-limit'] },
  { id: 'pg-advanced-l2-044', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you declare and use composite types in PL/pgSQL?', options: ['Use structs like in C programming', 'Define a TYPE with CREATE TYPE name AS (field1 type1, field2 type2) — composite types can then be used as variable types in PL/pgSQL, as function parameters and return types, and as table columns, providing structured data containers', 'Composite types are not supported', 'Use JSON objects instead'], correctAnswer: 3, explanation: 'Composite types (also called row types) define a structure with named fields. Every table automatically has an associated composite type with the same name. You can create standalone composite types with CREATE TYPE. In PL/pgSQL, you can declare variables of composite type and access fields with dot notation. They are useful for returning multiple values from functions.', codeSnippet: "-- Create a composite type:\nCREATE TYPE address AS (\n  street TEXT,\n  city TEXT,\n  zip TEXT,\n  country TEXT\n);\n\n-- Use in a function:\nCREATE FUNCTION parse_address(raw TEXT)\nRETURNS address AS $$\nDECLARE\n  result address;\nBEGIN\n  result.street := split_part(raw, ',', 1);\n  result.city := split_part(raw, ',', 2);\n  result.zip := split_part(raw, ',', 3);\n  result.country := split_part(raw, ',', 4);\n  RETURN result;\nEND;\n$$ LANGUAGE plpgsql;\n\nSELECT * FROM parse_address('123 Main,NYC,10001,US');\n-- street | city | zip   | country\n-- 123 Main| NYC | 10001 | US", tags: ['advanced', 'plpgsql', 'composite-types', 'create-type'] },
  { id: 'pg-advanced-l2-045', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'What is the PERFORM statement in PL/pgSQL?', options: ['PERFORM executes a query and returns results', 'PERFORM runs a query and discards the result — it is used to call functions or execute SQL statements when you do not need the return value, equivalent to SELECT but without the need to declare a variable to hold the unused result', 'PERFORM measures query performance', 'PERFORM runs queries asynchronously'], correctAnswer: 0, explanation: 'In PL/pgSQL, you cannot write a bare SELECT statement because PL/pgSQL expects the result to go somewhere (INTO variable). When you want to execute a function for its side effects or run a query whose result you do not need, use PERFORM instead of SELECT. PERFORM sets the FOUND variable, so you can check whether the query returned any rows.', codeSnippet: "DO $$\nBEGIN\n  -- Call a function for side effects:\n  PERFORM pg_notify('channel', 'hello');\n\n  -- Execute a query, discard result:\n  PERFORM id FROM users WHERE email = 'test@test.com';\n  IF FOUND THEN\n    RAISE NOTICE 'User exists';\n  END IF;\n\n  -- This would be an error:\n  -- SELECT pg_notify('ch', 'msg'); -- ERROR\n\n  -- PERFORM is essentially:\n  -- SELECT but discards the result\nEND;\n$$;", tags: ['advanced', 'plpgsql', 'perform', 'side-effects'] },
  { id: 'pg-advanced-l2-046', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you return a set of rows from a PL/pgSQL function?', options: ['Use RETURN SELECT to return all rows at once', 'Use RETURNS SETOF or RETURNS TABLE with RETURN NEXT for each row (or RETURN QUERY for a complete query result) — RETURN NEXT appends the current row to the result set, while RETURN QUERY appends all rows from a query', 'Functions can only return single values', 'Use output parameters exclusively'], correctAnswer: 1, explanation: 'Set-returning functions (SRFs) use RETURNS SETOF type or RETURNS TABLE(columns). RETURN NEXT adds the current values to the output. RETURN QUERY adds all rows from a query. Both can be used multiple times to build up the result set. The function call completes when RETURN (without NEXT/QUERY) is reached or the function ends. RETURN QUERY is more efficient for large result sets.', codeSnippet: "-- Using RETURN NEXT:\nCREATE FUNCTION fibonacci(n INTEGER)\nRETURNS SETOF BIGINT AS $$\nDECLARE\n  a BIGINT := 0; b BIGINT := 1; tmp BIGINT;\nBEGIN\n  FOR i IN 1..n LOOP\n    RETURN NEXT a;\n    tmp := a + b; a := b; b := tmp;\n  END LOOP;\nEND;\n$$ LANGUAGE plpgsql;\n\nSELECT * FROM fibonacci(10);\n\n-- Using RETURN QUERY:\nCREATE FUNCTION active_users_by_dept(dept TEXT)\nRETURNS TABLE(id INT, name TEXT, email TEXT) AS $$\nBEGIN\n  RETURN QUERY\n    SELECT u.id, u.name, u.email\n    FROM users u\n    WHERE u.department = dept AND u.active;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'plpgsql', 'return-next', 'return-query', 'set-returning'] },
  { id: 'pg-advanced-l2-047', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'Triggers', question: 'What is a deferred trigger in PostgreSQL?', options: ['A trigger that runs after a delay', 'A trigger that is disabled by default', 'A trigger created with CONSTRAINT option and INITIALLY DEFERRED — it fires at the end of the transaction instead of immediately after each row operation, useful when constraints need to be checked after all related changes in a transaction are complete', 'A trigger that only runs on weekends'], correctAnswer: 2, explanation: 'Constraint triggers (CREATE CONSTRAINT TRIGGER) can be deferred using DEFERRABLE INITIALLY DEFERRED. Unlike regular triggers which fire immediately after the triggering event, deferred triggers collect all events and fire at COMMIT time. This is essential for complex operations where related changes across multiple tables must all complete before validation. You can also change timing per-transaction with SET CONSTRAINTS.', codeSnippet: "-- Create a deferred constraint trigger:\nCREATE CONSTRAINT TRIGGER trg_check_balance\n  AFTER INSERT OR UPDATE ON transactions\n  DEFERRABLE INITIALLY DEFERRED\n  FOR EACH ROW\n  EXECUTE FUNCTION check_account_balance();\n\n-- The trigger fires at COMMIT:\nBEGIN;\n  UPDATE accounts SET balance = balance - 1000\n  WHERE id = 1;  -- might go negative temporarily\n  UPDATE accounts SET balance = balance + 1000\n  WHERE id = 2;\nCOMMIT;  -- trigger checks here, both balanced\n\n-- Change timing per-transaction:\nSET CONSTRAINTS trg_check_balance IMMEDIATE;\nSET CONSTRAINTS ALL DEFERRED;", tags: ['advanced', 'triggers', 'constraint-trigger', 'deferred'] },
  { id: 'pg-advanced-l2-048', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you use the STRICT option with SELECT INTO in PL/pgSQL?', options: ['STRICT makes the query case-sensitive', 'STRICT forces the query to use an index', 'SELECT INTO STRICT variable FROM ... raises an exception if the query returns zero rows (NO_DATA_FOUND) or more than one row (TOO_MANY_ROWS) — ensuring exactly one row is returned, which prevents silent data loss from ambiguous queries', 'STRICT disables NULL values in results'], correctAnswer: 3, explanation: 'Without STRICT, SELECT INTO silently returns NULL if no rows match and uses only the first row if multiple match. STRICT enforces that exactly one row is returned. This is important for correctness — without it, you might silently get wrong results when a query unexpectedly returns zero or multiple rows. The exceptions can be caught in an EXCEPTION block.', codeSnippet: "CREATE FUNCTION get_user(p_id INTEGER)\nRETURNS users AS $$\nDECLARE\n  result users;\nBEGIN\n  -- STRICT: must return exactly 1 row\n  SELECT * INTO STRICT result\n  FROM users WHERE id = p_id;\n  RETURN result;\nEXCEPTION\n  WHEN NO_DATA_FOUND THEN\n    RAISE EXCEPTION 'User % not found', p_id;\n  WHEN TOO_MANY_ROWS THEN\n    RAISE EXCEPTION 'Multiple users with id %', p_id;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Without STRICT:\n-- 0 rows → result is NULL (no error)\n-- 2+ rows → first row used (no error)\n-- With STRICT:\n-- 0 rows → NO_DATA_FOUND exception\n-- 2+ rows → TOO_MANY_ROWS exception", tags: ['advanced', 'plpgsql', 'select-into-strict', 'error-handling'] },
  { id: 'pg-advanced-l2-049', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'What is the difference between SECURITY DEFINER and SECURITY INVOKER functions?', options: ['SECURITY DEFINER encrypts the function code', 'SECURITY INVOKER requires authentication for each call', 'SECURITY DEFINER runs with the privileges of the function owner, while SECURITY INVOKER (the default) runs with the privileges of the calling user — SECURITY DEFINER is like setuid in Unix, allowing controlled privilege escalation', 'They control network security settings'], correctAnswer: 0, explanation: 'SECURITY DEFINER functions execute with the privileges of the user who created the function, regardless of who calls it. This enables controlled privilege escalation — users can perform specific operations they normally would not have permission for. This is powerful but risky: always set search_path explicitly in SECURITY DEFINER functions to prevent search_path-based attacks.', codeSnippet: "-- SECURITY DEFINER (runs as owner):\nCREATE FUNCTION reset_password(\n  user_id INT, new_hash TEXT\n) RETURNS VOID\nSECURITY DEFINER\nSET search_path = public  -- prevent attacks!\nAS $$\nBEGIN\n  UPDATE users SET password_hash = new_hash\n  WHERE id = user_id;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Even unprivileged users can call this:\n-- They can reset passwords through this\n-- controlled function, without having\n-- direct UPDATE access to the users table\n\n-- SECURITY INVOKER (default):\nCREATE FUNCTION get_my_data()\nRETURNS SETOF users\nSECURITY INVOKER AS $$\nBEGIN\n  RETURN QUERY SELECT * FROM users;\nEND;\n$$ LANGUAGE plpgsql;\n-- Runs with caller's permissions", tags: ['advanced', 'plpgsql', 'security-definer', 'privileges'] },
  { id: 'pg-advanced-l2-050', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you handle nested exception blocks in PL/pgSQL?', options: ['Nesting exception blocks is not allowed', 'Use separate functions for each error level', 'Nest BEGIN..EXCEPTION..END blocks inside each other — each nested block creates its own subtransaction savepoint, allowing fine-grained error recovery where inner blocks can fail without affecting the outer block state', 'Use global error handlers'], correctAnswer: 1, explanation: 'PL/pgSQL allows nesting of BEGIN..EXCEPTION..END blocks. Each block with an EXCEPTION clause creates a subtransaction (implicit savepoint). If an exception occurs, only the subtransaction for that block is rolled back. This allows retry patterns and partial failure handling. However, subtransactions have performance overhead, so avoid deeply nested exception blocks in hot paths.', codeSnippet: "CREATE FUNCTION batch_process(ids INTEGER[])\nRETURNS TABLE(id INTEGER, status TEXT) AS $$\nDECLARE\n  current_id INTEGER;\nBEGIN\n  FOREACH current_id IN ARRAY ids LOOP\n    id := current_id;\n    -- Inner block: catches errors per item\n    BEGIN\n      PERFORM process_item(current_id);\n      status := 'success';\n    EXCEPTION\n      WHEN foreign_key_violation THEN\n        status := 'missing reference';\n      WHEN OTHERS THEN\n        status := 'error: ' || SQLERRM;\n    END;\n    RETURN NEXT;\n    -- Outer loop continues even if inner fails\n  END LOOP;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Each iteration is its own subtransaction\n-- Failure in one item doesn't abort others", tags: ['advanced', 'plpgsql', 'nested-exceptions', 'subtransactions'] },
  { id: 'pg-advanced-l2-051', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'Triggers', question: 'How do you create an INSTEAD OF trigger for views?', options: ['Use BEFORE triggers on the underlying tables', 'Use AFTER triggers with view name', 'Create an INSTEAD OF trigger on a view — it replaces the default INSERT, UPDATE, or DELETE behavior with custom logic, allowing you to make views writable by implementing the DML operations against the underlying base tables', 'Views cannot have triggers'], correctAnswer: 2, explanation: 'INSTEAD OF triggers are the mechanism for making views updatable when automatic updatability rules are not satisfied (e.g., views with joins, aggregates, or DISTINCT). The trigger function receives NEW/OLD and must implement the actual modifications on the base tables. Unlike BEFORE/AFTER triggers which supplement the operation, INSTEAD OF replaces it entirely.', codeSnippet: "-- View joining two tables:\nCREATE VIEW user_profiles AS\nSELECT u.id, u.name, p.bio, p.avatar_url\nFROM users u\nJOIN profiles p ON p.user_id = u.id;\n\n-- Make the view insertable:\nCREATE FUNCTION insert_user_profile()\nRETURNS TRIGGER AS $$\nBEGIN\n  INSERT INTO users(id, name)\n  VALUES (NEW.id, NEW.name);\n\n  INSERT INTO profiles(user_id, bio, avatar_url)\n  VALUES (NEW.id, NEW.bio, NEW.avatar_url);\n\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_insert_profile\n  INSTEAD OF INSERT ON user_profiles\n  FOR EACH ROW\n  EXECUTE FUNCTION insert_user_profile();\n\n-- Now this works:\nINSERT INTO user_profiles(id, name, bio, avatar_url)\nVALUES (1, 'Alice', 'Developer', '/img/alice.jpg');", tags: ['advanced', 'triggers', 'instead-of', 'updatable-views'] },
  { id: 'pg-advanced-l2-052', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'What is the %TYPE attribute in PL/pgSQL variable declarations?', options: ['It defines a new data type', 'It casts a variable to a specific type', 'variable_name table.column%TYPE declares a variable with the same data type as a specific table column — ensuring the variable type automatically matches the column type even if the column type changes later', 'It creates a type alias'], correctAnswer: 3, explanation: '%TYPE anchors a variable declaration to a table column type. If the column type changes (e.g., from INTEGER to BIGINT), the variable automatically uses the new type on the next function call. This reduces maintenance burden and prevents type mismatch errors. Similarly, %ROWTYPE anchors to an entire row type of a table.', codeSnippet: "CREATE FUNCTION get_product_info(p_id INTEGER)\nRETURNS TEXT AS $$\nDECLARE\n  v_name products.name%TYPE;\n  v_price products.price%TYPE;\n  v_stock products.stock_quantity%TYPE;\nBEGIN\n  SELECT name, price, stock_quantity\n  INTO v_name, v_price, v_stock\n  FROM products WHERE id = p_id;\n\n  RETURN format('%s: $%s (%s in stock)',\n    v_name, v_price, v_stock);\nEND;\n$$ LANGUAGE plpgsql;\n\n-- %ROWTYPE for entire row:\nDECLARE\n  v_product products%ROWTYPE;\nBEGIN\n  SELECT * INTO v_product FROM products WHERE id = 1;\n  RAISE NOTICE '%', v_product.name;\nEND;", tags: ['advanced', 'plpgsql', 'percent-type', 'type-anchoring'] },
  { id: 'pg-advanced-l2-053', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'pg_trgm', question: 'How do you combine pg_trgm with full-text search for better results?', options: ['They cannot be combined', 'Replace full-text search with pg_trgm entirely', 'Use pg_trgm for fuzzy matching on short fields (names, titles) and tsvector/tsquery full-text search for longer content — combining both in queries allows typo-tolerant searches on structured fields while maintaining relevance ranking on text content', 'Use pg_trgm as a preprocessor for tsvector'], correctAnswer: 0, explanation: 'pg_trgm and full-text search (FTS) serve different purposes. FTS uses linguistic analysis (stemming, stop words) for document search with ranking. pg_trgm uses character-level similarity for fuzzy matching without linguistic awareness. Combining them provides typo tolerance (pg_trgm) with semantic relevance (FTS). A common pattern is using pg_trgm for "did you mean?" suggestions and FTS for the main search.', codeSnippet: "-- Combined search function:\nCREATE FUNCTION search_articles(\n  query TEXT,\n  fuzzy_threshold REAL DEFAULT 0.3\n) RETURNS TABLE(\n  id INT, title TEXT, score REAL\n) AS $$\nBEGIN\n  SET pg_trgm.similarity_threshold = fuzzy_threshold;\n\n  RETURN QUERY\n  SELECT a.id, a.title,\n    (ts_rank(a.content_tsv,\n      plainto_tsquery('english', query))\n     + similarity(a.title, query)\n    )::REAL AS score\n  FROM articles a\n  WHERE a.content_tsv @@ plainto_tsquery('english', query)\n     OR a.title % query\n  ORDER BY score DESC\n  LIMIT 20;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'pg-trgm', 'full-text-search', 'combined-search'] },
  { id: 'pg-advanced-l2-054', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'Triggers', question: 'How do you prevent infinite trigger recursion in PostgreSQL?', options: ['PostgreSQL automatically prevents all recursion', 'Use the pg_trigger_depth() function to check the current trigger nesting level — if the depth is greater than zero, the trigger was fired by another trigger, allowing you to skip execution and prevent infinite loops', 'Trigger recursion is impossible in PostgreSQL', 'Use DISABLE TRIGGER inside the trigger'], correctAnswer: 1, explanation: 'pg_trigger_depth() returns the current nesting level of trigger execution (0 when not inside a trigger). This is essential when a trigger on table A modifies table B, which has a trigger that modifies table A, potentially causing infinite recursion. Checking pg_trigger_depth() at the start of the trigger function and returning early if too deep prevents this. PostgreSQL has a hard limit on stack depth but relying on it is bad practice.', codeSnippet: "CREATE FUNCTION prevent_recursion()\nRETURNS TRIGGER AS $$\nBEGIN\n  -- Skip if called from another trigger:\n  IF pg_trigger_depth() > 1 THEN\n    RETURN NEW;\n  END IF;\n\n  -- Safe to proceed with trigger logic:\n  UPDATE related_table\n  SET synced = TRUE\n  WHERE ref_id = NEW.id;\n\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Alternative: use a session variable as guard\nCREATE FUNCTION guarded_trigger()\nRETURNS TRIGGER AS $$\nBEGIN\n  IF current_setting('app.in_trigger', TRUE) = 'true' THEN\n    RETURN NEW;\n  END IF;\n\n  PERFORM set_config('app.in_trigger', 'true', TRUE);\n  -- ... trigger logic ...\n  PERFORM set_config('app.in_trigger', 'false', TRUE);\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'triggers', 'recursion-prevention', 'pg-trigger-depth'] },
  { id: 'pg-advanced-l2-055', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'LISTEN/NOTIFY', question: 'How do you consume NOTIFY messages in application code?', options: ['Poll a special notification table', 'Use a stored procedure that blocks', 'Use the asynchronous notification API of your database driver — most PostgreSQL drivers (libpq, psycopg2, node-postgres, JDBC) provide methods to register listeners and receive notifications asynchronously or via polling', 'Parse the PostgreSQL server log'], correctAnswer: 2, explanation: 'Each PostgreSQL client driver has its own API for LISTEN/NOTIFY. In Python (psycopg2), you call conn.poll() and check conn.notifies. In Node.js (pg), you use client.on("notification", callback). In Java (JDBC), you cast to PGConnection and call getNotifications(). The application must maintain an active connection listening on the channel. Connection poolers like PgBouncer can interfere with LISTEN in transaction mode.', codeSnippet: "-- Python (psycopg2):\nimport psycopg2\nimport select\n\nconn = psycopg2.connect(dsn)\nconn.autocommit = True\ncur = conn.cursor()\ncur.execute('LISTEN order_events;')\n\nwhile True:\n    select.select([conn], [], [], 5)  # 5s timeout\n    conn.poll()\n    while conn.notifies:\n        notify = conn.notifies.pop(0)\n        print(f'Channel: {notify.channel}')\n        print(f'Payload: {notify.payload}')\n\n-- Node.js (pg):\nconst client = new Client();\nawait client.connect();\nawait client.query('LISTEN order_events');\nclient.on('notification', (msg) => {\n  console.log(msg.channel, msg.payload);\n});", tags: ['advanced', 'listen-notify', 'application-code', 'drivers'] },
  { id: 'pg-advanced-l2-056', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you create a function that accepts variadic arguments?', options: ['Use the ... syntax like in JavaScript', 'Use VARIADIC parameter_name type[] — which allows the function to accept a variable number of arguments of the specified type, collected into an array, enabling flexible function signatures', 'Variadic functions are not supported', 'Use overloaded functions for each argument count'], correctAnswer: 3, explanation: 'VARIADIC parameters accept a variable number of arguments that are collected into an array. The VARIADIC keyword must be on the last parameter. Callers can pass individual values (auto-collected) or an array with VARIADIC keyword. You can also combine regular parameters with a VARIADIC parameter. Inside the function, the variadic parameter is a regular array.', codeSnippet: "CREATE FUNCTION concat_with_sep(\n  sep TEXT, VARIADIC parts TEXT[]\n) RETURNS TEXT AS $$\nBEGIN\n  RETURN array_to_string(parts, sep);\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Call with individual arguments:\nSELECT concat_with_sep('-', 'a', 'b', 'c');\n-- Result: 'a-b-c'\n\nSELECT concat_with_sep(', ', 'one', 'two', 'three');\n-- Result: 'one, two, three'\n\n-- Call with array using VARIADIC keyword:\nSELECT concat_with_sep('-',\n  VARIADIC ARRAY['x', 'y', 'z']);\n-- Result: 'x-y-z'", tags: ['advanced', 'plpgsql', 'variadic', 'flexible-arguments'] },
  { id: 'pg-advanced-l2-057', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'What is the difference between VOLATILE, STABLE, and IMMUTABLE function volatility categories?', options: ['They control function access permissions', 'They determine function execution priority', 'VOLATILE (default) can modify database and return different results per call, STABLE returns consistent results within a single query scan but does not modify data, IMMUTABLE always returns the same result for the same inputs — these help the optimizer decide when to cache or inline function results', 'They control memory allocation for functions'], correctAnswer: 0, explanation: 'Volatility categories are optimizer hints. IMMUTABLE functions can be pre-evaluated at plan time for constant arguments and used in index expressions. STABLE functions are evaluated once per query scan, enabling optimizations like index scans with function calls. VOLATILE functions must be re-evaluated for every row. Incorrect labeling can cause wrong results (e.g., labeling a function that reads changing data as IMMUTABLE).', codeSnippet: "-- IMMUTABLE: pure function, always same result\nCREATE FUNCTION celsius_to_fahrenheit(c NUMERIC)\nRETURNS NUMERIC AS $$\nBEGIN\n  RETURN c * 9.0 / 5.0 + 32;\nEND;\n$$ LANGUAGE plpgsql IMMUTABLE;\n\n-- STABLE: consistent within one query\nCREATE FUNCTION get_setting_value(key TEXT)\nRETURNS TEXT AS $$\nBEGIN\n  RETURN (SELECT value FROM settings WHERE name = key);\nEND;\n$$ LANGUAGE plpgsql STABLE;\n\n-- VOLATILE: may change on each call (default)\nCREATE FUNCTION next_sequence_val(seq TEXT)\nRETURNS BIGINT AS $$\nBEGIN\n  RETURN nextval(seq);\nEND;\n$$ LANGUAGE plpgsql VOLATILE;", tags: ['advanced', 'plpgsql', 'volatility', 'optimizer-hints'] },
  { id: 'pg-advanced-l2-058', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'Triggers', question: 'How do you create a trigger that logs all changes to an audit table?', options: ['Use PostgreSQL built-in audit logging', 'Write an application-level middleware', 'Create an AFTER trigger function that inserts a record into an audit table for each INSERT, UPDATE, and DELETE — capturing the operation type, old and new row data (as JSON), timestamp, and the user who made the change', 'Enable the pgaudit extension only'], correctAnswer: 1, explanation: 'Trigger-based audit logging is a common pattern that captures every data change at the database level, regardless of which application made the change. Using row_to_json() or to_jsonb() converts entire rows to JSON for flexible storage. AFTER triggers are preferred because the operation has already succeeded. This approach provides a complete, tamper-resistant audit trail.', codeSnippet: "CREATE TABLE audit_log (\n  id BIGSERIAL PRIMARY KEY,\n  table_name TEXT NOT NULL,\n  operation TEXT NOT NULL,\n  old_data JSONB,\n  new_data JSONB,\n  changed_by TEXT DEFAULT current_user,\n  changed_at TIMESTAMPTZ DEFAULT now()\n);\n\nCREATE FUNCTION audit_trigger()\nRETURNS TRIGGER AS $$\nBEGIN\n  INSERT INTO audit_log(table_name, operation, old_data, new_data)\n  VALUES (\n    TG_TABLE_NAME,\n    TG_OP,\n    CASE WHEN TG_OP IN ('UPDATE','DELETE')\n      THEN to_jsonb(OLD) END,\n    CASE WHEN TG_OP IN ('INSERT','UPDATE')\n      THEN to_jsonb(NEW) END\n  );\n  RETURN COALESCE(NEW, OLD);\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_audit\n  AFTER INSERT OR UPDATE OR DELETE ON orders\n  FOR EACH ROW EXECUTE FUNCTION audit_trigger();", tags: ['advanced', 'triggers', 'audit-log', 'change-tracking'] },
  { id: 'pg-advanced-l2-059', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'postgres_fdw', question: 'How do you handle authentication securely with postgres_fdw?', options: ['Store passwords in plain text in the mapping', 'Use CREATE USER MAPPING with password options and restrict access to the pg_user_mappings catalog — additionally, consider using certificate-based authentication or password files (.pgpass) on the server to avoid storing credentials in catalog tables', 'postgres_fdw does not support authentication', 'Use environment variables for passwords'], correctAnswer: 2, explanation: 'User mappings store credentials for connecting to remote servers. While passwords are stored in pg_user_mappings (visible to superusers and the mapped user), you can enhance security by using certificate-based SSL authentication, pg_ident.conf mappings, or .pgpass files. The password_required option (PG 14+) can prevent non-superusers from creating mappings without passwords. Always use SSL (sslmode) for encrypted connections.', codeSnippet: "-- Basic user mapping:\nCREATE USER MAPPING FOR app_user\n  SERVER remote_db\n  OPTIONS (user 'remote_app', password 'secret');\n\n-- SSL connection:\nALTER SERVER remote_db\n  OPTIONS (ADD sslmode 'require');\n\n-- Certificate-based auth (no password):\nALTER SERVER remote_db\n  OPTIONS (\n    ADD sslmode 'verify-full',\n    ADD sslcert '/path/to/client.crt',\n    ADD sslkey '/path/to/client.key',\n    ADD sslrootcert '/path/to/ca.crt'\n  );\n\n-- Check mappings (limited visibility):\nSELECT * FROM pg_user_mappings;\n-- Non-superusers see ***** for passwords", tags: ['advanced', 'postgres-fdw', 'security', 'user-mapping'] },
  { id: 'pg-advanced-l2-060', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you use RETURN QUERY EXECUTE for dynamic set-returning functions?', options: ['RETURN QUERY EXECUTE is not valid syntax', 'Use RETURN NEXT with EXECUTE instead', 'RETURN QUERY EXECUTE runs a dynamically constructed SQL string and appends all result rows to the function output — combining the flexibility of dynamic SQL with the efficiency of set-returning functions', 'Use CREATE TEMPORARY TABLE with EXECUTE'], correctAnswer: 3, explanation: 'RETURN QUERY EXECUTE is the dynamic SQL counterpart of RETURN QUERY. It constructs and executes a SQL query at runtime and returns all resulting rows. This is essential when table names, column names, or query structure must be determined at runtime. It supports USING for parameter binding, just like regular EXECUTE. This avoids the overhead of fetching rows one by one with cursors.', codeSnippet: "CREATE FUNCTION dynamic_search(\n  tbl TEXT, col TEXT, val TEXT\n) RETURNS SETOF RECORD AS $$\nBEGIN\n  RETURN QUERY EXECUTE format(\n    'SELECT * FROM %I WHERE %I = $1',\n    tbl, col\n  ) USING val;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- With RETURNS TABLE for typed results:\nCREATE FUNCTION search_any_table(\n  tbl TEXT, search_col TEXT, search_val TEXT\n) RETURNS TABLE(id INT, name TEXT) AS $$\nBEGIN\n  RETURN QUERY EXECUTE format(\n    'SELECT id, name FROM %I WHERE %I ILIKE $1',\n    tbl, search_col\n  ) USING '%' || search_val || '%';\nEND;\n$$ LANGUAGE plpgsql;\n\nSELECT * FROM search_any_table(\n  'products', 'name', 'phone'\n);", tags: ['advanced', 'plpgsql', 'return-query-execute', 'dynamic-sql'] },
  { id: 'pg-advanced-l2-061', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'What is the difference between RECORD and a concrete row type in PL/pgSQL?', options: ['RECORD is faster than concrete row types', 'They are identical in all aspects', 'RECORD is a polymorphic placeholder that takes on the structure of whatever row is assigned to it — it has no predefined columns and cannot be used until assigned, while concrete row types (table%ROWTYPE or composite types) have fixed known columns', 'RECORD can only hold integer values'], correctAnswer: 0, explanation: 'RECORD variables are untyped until a row is assigned. After assignment, they adopt the column structure of the assigned row. This makes them flexible but the compiler cannot check field references at definition time. Concrete types (users%ROWTYPE, custom composite types) have known columns at compile time, enabling better error checking. RECORD is useful when the function handles different table structures dynamically.', codeSnippet: "-- RECORD: flexible, shape determined at runtime\nCREATE FUNCTION show_any_row(tbl TEXT, row_id INT)\nRETURNS TEXT AS $$\nDECLARE\n  r RECORD;\nBEGIN\n  EXECUTE format('SELECT * FROM %I WHERE id = $1', tbl)\n  INTO r USING row_id;\n  RETURN row_to_json(r)::TEXT;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Concrete type: fixed structure, compile-time checks\nCREATE FUNCTION get_user(uid INT)\nRETURNS users AS $$\nDECLARE\n  u users%ROWTYPE;\nBEGIN\n  SELECT * INTO u FROM users WHERE id = uid;\n  -- u.name OK — compiler knows 'name' exists\n  RETURN u;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'plpgsql', 'record-type', 'rowtype'] },
  { id: 'pg-advanced-l2-062', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'Triggers', question: 'How do you enable and disable triggers on a table?', options: ['Use START TRIGGER and STOP TRIGGER', 'Use GRANT and REVOKE on trigger privileges', 'Use ALTER TABLE ... ENABLE/DISABLE TRIGGER — you can disable a specific trigger by name, all triggers with ALL, or just user-defined triggers with USER, and re-enable them with ENABLE TRIGGER', 'Triggers cannot be disabled once created'], correctAnswer: 1, explanation: 'Disabling triggers is useful during bulk data loads, migrations, or maintenance operations where trigger overhead is unwanted. DISABLE TRIGGER name disables a specific trigger, DISABLE TRIGGER ALL disables all triggers (including system triggers for foreign keys), and DISABLE TRIGGER USER disables only user-defined triggers. Re-enable with ENABLE TRIGGER. Only the table owner or superuser can disable triggers.', codeSnippet: "-- Disable a specific trigger:\nALTER TABLE orders DISABLE TRIGGER trg_audit;\n\n-- Disable all user triggers:\nALTER TABLE orders DISABLE TRIGGER USER;\n\n-- Disable ALL triggers (including FK checks!):\nALTER TABLE orders DISABLE TRIGGER ALL;\n\n-- Bulk load without trigger overhead:\nALTER TABLE orders DISABLE TRIGGER USER;\nCOPY orders FROM '/data/orders.csv' CSV HEADER;\nALTER TABLE orders ENABLE TRIGGER USER;\n\n-- Re-enable:\nALTER TABLE orders ENABLE TRIGGER trg_audit;\nALTER TABLE orders ENABLE TRIGGER ALL;\n\n-- ENABLE ALWAYS: fires even during replication\nALTER TABLE orders\n  ENABLE ALWAYS TRIGGER trg_audit;", tags: ['advanced', 'triggers', 'enable-disable', 'bulk-operations'] },
  { id: 'pg-advanced-l2-063', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'Materialized Views', question: 'How do you check when a materialized view was last refreshed?', options: ['Use SELECT last_refresh FROM pg_matviews', 'Query the pg_stat_user_tables view for the last analyze time', 'PostgreSQL does not natively track the last refresh time — you must implement tracking yourself, typically by querying pg_stat_user_tables for last_autovacuum/last_autoanalyze timestamps or by adding a refresh timestamp column or tracking table', 'Use SHOW MATERIALIZED VIEW STATUS'], correctAnswer: 2, explanation: 'Unlike some databases, PostgreSQL does not store the last refresh timestamp for materialized views. Common workarounds include: creating a tracking table updated by your refresh script, adding a refresh_timestamp column to the materialized view query (using now()), or checking file modification times of the relation files. pg_stat_user_tables tracks DML statistics but not materialized view refreshes directly.', codeSnippet: "-- Workaround 1: Tracking table\nCREATE TABLE mv_refresh_log (\n  view_name TEXT PRIMARY KEY,\n  refreshed_at TIMESTAMPTZ\n);\n\n-- Refresh with logging:\nCREATE FUNCTION refresh_mv(mv TEXT)\nRETURNS VOID AS $$\nBEGIN\n  EXECUTE 'REFRESH MATERIALIZED VIEW CONCURRENTLY '\n    || quote_ident(mv);\n  INSERT INTO mv_refresh_log VALUES (mv, now())\n  ON CONFLICT (view_name)\n  DO UPDATE SET refreshed_at = now();\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Workaround 2: Include timestamp in view\nCREATE MATERIALIZED VIEW mv_data AS\nSELECT *, now() AS refreshed_at\nFROM source_table;\n\nSELECT DISTINCT refreshed_at FROM mv_data;", tags: ['advanced', 'materialized-views', 'refresh-tracking', 'monitoring'] },
  { id: 'pg-advanced-l2-064', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you use OUT parameters in PL/pgSQL functions?', options: ['OUT parameters are output-only variables listed in the function signature — they are automatically returned at the end of the function without an explicit RETURN statement, and multiple OUT parameters create an implicit composite return type', 'OUT parameters are the same as regular parameters', 'OUT parameters must be returned with RETURN statement', 'PL/pgSQL does not support OUT parameters'], correctAnswer: 3, explanation: 'OUT parameters provide an alternative to RETURNS for functions that return multiple values. They are declared in the parameter list with the OUT keyword and are automatically part of the return value. You can assign to them like local variables. When a function has OUT parameters, RETURN without a value is allowed (it returns the current OUT values). Multiple OUT parameters are equivalent to RETURNS RECORD.', codeSnippet: "-- Multiple return values with OUT:\nCREATE FUNCTION get_stats(\n  IN table_name TEXT,\n  OUT row_count BIGINT,\n  OUT total_size TEXT,\n  OUT index_size TEXT\n) AS $$\nBEGIN\n  EXECUTE format(\n    'SELECT COUNT(*) FROM %I', table_name\n  ) INTO row_count;\n\n  total_size := pg_size_pretty(\n    pg_total_relation_size(table_name));\n  index_size := pg_size_pretty(\n    pg_indexes_size(table_name));\n  -- No RETURN needed: OUT params auto-returned\nEND;\n$$ LANGUAGE plpgsql;\n\nSELECT * FROM get_stats('users');\n-- row_count | total_size | index_size\n-- 50000     | 12 MB      | 3 MB", tags: ['advanced', 'plpgsql', 'out-parameters', 'multiple-returns'] },
  { id: 'pg-advanced-l2-065', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'pg_trgm', question: 'How do you use pg_trgm for autocomplete suggestions?', options: ['Use a simple LIKE query without any index', 'Use full-text search with tsquery', 'Combine a GiST trigram index with ORDER BY distance (<->) operator to return the closest matches sorted by similarity — this enables real-time, typo-tolerant autocomplete with KNN (k-nearest-neighbor) ordering', 'Use a bloom filter index'], correctAnswer: 0, explanation: 'The <-> operator returns the trigram distance (1 - similarity) between strings. Combined with a GiST index, PostgreSQL can efficiently find the nearest matches using KNN (k-nearest-neighbor) index scan, without needing to compute similarity for every row. This is ideal for autocomplete because it handles typos gracefully and returns results ordered by relevance with sub-millisecond response times.', codeSnippet: "-- Create GiST index for KNN support:\nCREATE INDEX idx_product_name_gist\n  ON products USING gist (name gist_trgm_ops);\n\n-- Autocomplete query:\nSELECT name, name <-> 'lapt' AS distance\nFROM products\nORDER BY name <-> 'lapt'\nLIMIT 10;\n-- Returns: Laptop, Laptop Pro, Laptop Air, etc.\n\n-- Handles typos:\nSELECT name, name <-> 'lapttop' AS distance\nFROM products\nORDER BY name <-> 'lapttop'\nLIMIT 5;\n-- Still returns Laptop results\n\n-- Combined with prefix matching:\nSELECT name\nFROM products\nWHERE name ILIKE 'lap%'\n   OR name % 'lap'\nORDER BY name <-> 'lap'\nLIMIT 10;", tags: ['advanced', 'pg-trgm', 'autocomplete', 'knn-search'] },
  { id: 'pg-advanced-l2-066', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'Triggers', question: 'What is the firing order of multiple triggers on the same table?', options: ['Triggers fire in the order they were created', 'The order is random and unpredictable', 'Multiple triggers on the same table and event fire in alphabetical order by trigger name — this is deterministic and can be relied upon, so naming conventions (e.g., using numeric prefixes) can control execution order', 'Only one trigger can exist per table per event'], correctAnswer: 1, explanation: 'When multiple triggers are defined for the same table, event, and timing (e.g., two BEFORE INSERT triggers), they fire in alphabetical order by name. This is a PostgreSQL-specific behavior. You can exploit this by naming triggers with numeric prefixes (01_validate, 02_transform, 03_log). Each trigger function receives the possibly-modified NEW from the previous trigger in the chain.', codeSnippet: "-- Fires in order: 01, 02, 03\nCREATE TRIGGER trg_01_validate\n  BEFORE INSERT ON orders\n  FOR EACH ROW\n  EXECUTE FUNCTION validate_order();\n\nCREATE TRIGGER trg_02_transform\n  BEFORE INSERT ON orders\n  FOR EACH ROW\n  EXECUTE FUNCTION transform_order();\n\nCREATE TRIGGER trg_03_log\n  BEFORE INSERT ON orders\n  FOR EACH ROW\n  EXECUTE FUNCTION log_order();\n\n-- Each trigger receives NEW as modified by\n-- the previous trigger in the chain.\n-- If any returns NULL, subsequent triggers\n-- are skipped and the INSERT is cancelled.", tags: ['advanced', 'triggers', 'firing-order', 'alphabetical'] },
  { id: 'pg-advanced-l2-067', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'What is the difference between a PL/pgSQL function and a procedure?', options: ['They are identical in every way', 'Procedures are faster than functions', 'Procedures (CREATE PROCEDURE) can manage transactions with COMMIT and ROLLBACK inside them, while functions cannot — procedures are called with CALL and do not return a value, making them suitable for complex multi-step operations requiring transaction control', 'Functions can only read data, procedures can write'], correctAnswer: 2, explanation: 'Procedures were introduced in PostgreSQL 11. The key difference is transaction control: procedures can COMMIT and ROLLBACK within their body, allowing long-running operations to commit work in batches. Functions always run within the calling transaction and cannot commit. Procedures are invoked with CALL (not SELECT). They do not have a return value, though they can use INOUT parameters for output.', codeSnippet: "-- Procedure with transaction control:\nCREATE PROCEDURE batch_archive(\n  days_old INTEGER DEFAULT 90\n)\nAS $$\nDECLARE\n  batch_size INTEGER := 1000;\n  affected INTEGER;\nBEGIN\n  LOOP\n    DELETE FROM events\n    WHERE created_at < now() - (days_old || ' days')::INTERVAL\n    LIMIT batch_size;\n\n    GET DIAGNOSTICS affected = ROW_COUNT;\n    EXIT WHEN affected = 0;\n\n    COMMIT;  -- commit each batch!\n    RAISE NOTICE 'Archived % rows', affected;\n  END LOOP;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Call the procedure:\nCALL batch_archive(90);\nCALL batch_archive(); -- uses default", tags: ['advanced', 'plpgsql', 'procedures', 'transaction-control'] },
  { id: 'pg-advanced-l2-068', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'LISTEN/NOTIFY', question: 'How do you use LISTEN/NOTIFY for cache invalidation?', options: ['Cache invalidation cannot be done with NOTIFY', 'Use NOTIFY to broadcast cache invalidation events when data changes — application servers listening on the channel can immediately clear or update their local caches, providing near-instant invalidation without polling or TTL-based expiration', 'Use Redis pub/sub instead', 'Poll the database for changes periodically'], correctAnswer: 3, explanation: 'LISTEN/NOTIFY is an efficient cache invalidation mechanism. When a row is modified, a trigger sends a NOTIFY with details about what changed. Application servers listening on the channel can surgically invalidate only the affected cache entries. This is faster than TTL-based expiration (which serves stale data) and more efficient than polling (which wastes resources). It works well with connection per application server.', codeSnippet: "-- Trigger to notify cache invalidation:\nCREATE FUNCTION invalidate_cache()\nRETURNS TRIGGER AS $$\nBEGIN\n  PERFORM pg_notify(\n    'cache_invalidation',\n    json_build_object(\n      'table', TG_TABLE_NAME,\n      'op', TG_OP,\n      'key', COALESCE(NEW.id, OLD.id)\n    )::TEXT\n  );\n  RETURN COALESCE(NEW, OLD);\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_cache_products\n  AFTER INSERT OR UPDATE OR DELETE ON products\n  FOR EACH ROW\n  EXECUTE FUNCTION invalidate_cache();\n\n-- App server:\n-- LISTEN cache_invalidation;\n-- On notification: cache.delete(payload.key)", tags: ['advanced', 'listen-notify', 'cache-invalidation', 'real-time'] },
  { id: 'pg-advanced-l2-069', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you use the format() function for safe dynamic SQL?', options: ['format() is just a string formatting function', 'format() is only for log messages', 'format() with %I (identifier quoting), %L (literal quoting), and %s (simple substitution) provides SQL-injection-safe string building for dynamic queries — %I applies quote_ident() and %L applies quote_literal() automatically', 'format() cannot be used with EXECUTE'], correctAnswer: 0, explanation: 'format() is the recommended way to build dynamic SQL strings. %I safely quotes identifiers (table/column names) using double quotes only when needed. %L safely quotes literal values with proper escaping. %s does simple substitution without quoting. Always use %I for identifiers and USING clause (with $1, $2 placeholders) for values in EXECUTE statements for maximum safety.', codeSnippet: "-- %I for identifiers, %L for literals:\nSELECT format('SELECT * FROM %I WHERE %I = %L',\n  'user_table', 'name', 'O''Brien');\n-- SELECT * FROM user_table WHERE name = 'O''Brien'\n\n-- Safe dynamic table operations:\nCREATE FUNCTION truncate_table(tbl TEXT)\nRETURNS VOID AS $$\nBEGIN\n  -- %I prevents SQL injection via table name:\n  EXECUTE format('TRUNCATE TABLE %I', tbl);\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Combine format with USING:\nCREATE FUNCTION find_by_field(\n  tbl TEXT, col TEXT, val TEXT\n) RETURNS SETOF RECORD AS $$\nBEGIN\n  RETURN QUERY EXECUTE format(\n    'SELECT * FROM %I WHERE %I = $1', tbl, col\n  ) USING val;  -- $1 bound safely\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'plpgsql', 'format', 'sql-injection-prevention'] },
  { id: 'pg-advanced-l2-070', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'Triggers', question: 'How do transition tables work with AFTER triggers?', options: ['Transition tables are temporary tables for migrations', 'Transition tables are used during table alterations', 'REFERENCING OLD TABLE AS and NEW TABLE AS clauses in AFTER statement-level triggers provide access to the complete set of old and new rows affected by the statement — enabling efficient bulk processing instead of row-by-row trigger execution', 'Transition tables store trigger history'], correctAnswer: 1, explanation: 'Transition tables (introduced in PostgreSQL 10) allow statement-level AFTER triggers to access all affected rows at once using table aliases. OLD TABLE contains pre-modification rows and NEW TABLE contains post-modification rows. This is much more efficient than row-level triggers for bulk operations because the trigger function runs once and can process all changes using standard SQL queries on the transition tables.', codeSnippet: "CREATE FUNCTION bulk_audit()\nRETURNS TRIGGER AS $$\nBEGIN\n  -- Insert all changes at once (efficient!):\n  INSERT INTO audit_log(table_name, op, old_data, new_data)\n  SELECT TG_TABLE_NAME, TG_OP,\n    to_jsonb(o), to_jsonb(n)\n  FROM old_rows o\n  FULL JOIN new_rows n ON o.id = n.id;\n  RETURN NULL;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_bulk_audit\n  AFTER UPDATE ON orders\n  REFERENCING OLD TABLE AS old_rows\n             NEW TABLE AS new_rows\n  FOR EACH STATEMENT\n  EXECUTE FUNCTION bulk_audit();\n\n-- Single UPDATE affecting 1000 rows:\n-- Trigger fires ONCE with all rows accessible", tags: ['advanced', 'triggers', 'transition-tables', 'bulk-processing'] },
  { id: 'pg-advanced-l2-071', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you create a PL/pgSQL function with default parameter values?', options: ['Default parameters are not supported in PL/pgSQL', 'Use COALESCE inside the function body', 'Specify DEFAULT value or = value after the parameter type in the function signature — parameters with defaults can be omitted when calling the function, and must come after parameters without defaults', 'Use overloaded functions instead'], correctAnswer: 2, explanation: 'Default parameter values allow callers to omit trailing arguments. PostgreSQL supports DEFAULT keyword or = operator for specifying defaults. Parameters with defaults must be after required parameters. You can also use named parameter notation (param_name => value) to skip middle parameters with defaults. This reduces the need for function overloading.', codeSnippet: "CREATE FUNCTION paginated_search(\n  search_term TEXT,\n  page_size INTEGER DEFAULT 20,\n  page_num INTEGER DEFAULT 1,\n  sort_by TEXT DEFAULT 'created_at',\n  sort_dir TEXT DEFAULT 'DESC'\n) RETURNS SETOF products AS $$\nBEGIN\n  RETURN QUERY EXECUTE format(\n    'SELECT * FROM products\n     WHERE name ILIKE $1\n     ORDER BY %I %s\n     LIMIT $2 OFFSET $3',\n    sort_by, sort_dir\n  ) USING '%' || search_term || '%',\n    page_size,\n    (page_num - 1) * page_size;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Calls:\nSELECT * FROM paginated_search('phone');\nSELECT * FROM paginated_search('phone', 10, 2);\nSELECT * FROM paginated_search(\n  'phone', sort_by => 'price');", tags: ['advanced', 'plpgsql', 'default-parameters', 'named-notation'] },
  { id: 'pg-advanced-l2-072', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'Materialized Views', question: 'How do you create indexes on materialized views?', options: ['Materialized views cannot have indexes', 'Use CREATE INDEX just like on a regular table — materialized views support all standard index types (B-tree, GIN, GiST, BRIN, hash), allowing you to optimize query performance against the materialized data', 'Only the UNIQUE index type is supported', 'Indexes are automatically created on materialized views'], correctAnswer: 3, explanation: 'Materialized views are physically stored tables, so they support all index types. Creating appropriate indexes is essential since materialized views often store pre-aggregated or denormalized data that is queried frequently. Indexes are preserved across REFRESH operations. A UNIQUE index is required for REFRESH CONCURRENTLY. You can create multiple indexes for different query patterns.', codeSnippet: "CREATE MATERIALIZED VIEW mv_product_stats AS\nSELECT\n  p.id AS product_id,\n  p.name,\n  p.category,\n  COUNT(*) AS order_count,\n  SUM(oi.quantity) AS total_sold,\n  AVG(oi.price) AS avg_price\nFROM products p\nJOIN order_items oi ON oi.product_id = p.id\nGROUP BY p.id, p.name, p.category;\n\n-- Unique index (required for CONCURRENTLY):\nCREATE UNIQUE INDEX ON mv_product_stats (product_id);\n\n-- Additional indexes for queries:\nCREATE INDEX ON mv_product_stats (category);\nCREATE INDEX ON mv_product_stats (total_sold DESC);\nCREATE INDEX ON mv_product_stats\n  USING gin (name gin_trgm_ops); -- fuzzy search", tags: ['advanced', 'materialized-views', 'indexes', 'query-optimization'] },
  { id: 'pg-advanced-l2-073', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'What is the PARALLEL SAFE annotation for functions?', options: ['It makes the function run in multiple threads', 'It locks the function for exclusive access', 'PARALLEL SAFE tells the query planner that a function can be safely executed by parallel worker processes — along with PARALLEL RESTRICTED (only in leader) and PARALLEL UNSAFE (prevents parallelism), it controls how the function participates in parallel queries', 'It synchronizes function calls across sessions'], correctAnswer: 0, explanation: 'PostgreSQL can execute queries using multiple parallel workers. Functions default to PARALLEL UNSAFE, which prevents the query from using parallel execution when the function is involved. PARALLEL SAFE means the function can run in any worker. PARALLEL RESTRICTED means it can only run in the leader process. Correctly labeling functions enables parallel query execution, significantly improving performance on large datasets.', codeSnippet: "-- PARALLEL SAFE: can run in parallel workers\nCREATE FUNCTION clean_text(t TEXT)\nRETURNS TEXT AS $$\nBEGIN\n  RETURN LOWER(TRIM(regexp_replace(t, '\\s+', ' ', 'g')));\nEND;\n$$ LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE;\n\n-- PARALLEL RESTRICTED: leader process only\nCREATE FUNCTION get_config(key TEXT)\nRETURNS TEXT AS $$\nBEGIN\n  RETURN current_setting(key);\nEND;\n$$ LANGUAGE plpgsql STABLE PARALLEL RESTRICTED;\n\n-- PARALLEL UNSAFE: prevents parallelism\nCREATE FUNCTION log_call()\nRETURNS VOID AS $$\nBEGIN\n  INSERT INTO call_log VALUES (now());\nEND;\n$$ LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE;\n\n-- Check parallel safety:\nSELECT proname, proparallel\nFROM pg_proc WHERE proname = 'clean_text';", tags: ['advanced', 'plpgsql', 'parallel-safe', 'query-parallelism'] },
  { id: 'pg-advanced-l2-074', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'postgres_fdw', question: 'How do you join local and foreign tables in postgres_fdw?', options: ['Local and foreign tables cannot be joined', 'Joins between local and foreign tables work transparently — PostgreSQL treats foreign tables as regular tables in queries, and the optimizer can push down joins between foreign tables on the same remote server while fetching data for cross-server joins', 'You must use UNION instead of JOIN', 'Use dblink for cross-server joins'], correctAnswer: 1, explanation: 'PostgreSQL seamlessly joins local and foreign tables. When joining two foreign tables from the same remote server, the join can be pushed down to the remote server (remote join pushdown). For joins between a local and foreign table, PostgreSQL fetches the foreign data and performs the join locally. The optimizer considers which strategy is most efficient based on table sizes and available statistics.', codeSnippet: "-- Join local and foreign tables:\nSELECT l.id, l.name, r.order_total\nFROM local_customers l\nJOIN remote_orders r ON r.customer_id = l.id\nWHERE l.active = TRUE;\n\n-- Join two foreign tables (same server):\n-- Join is pushed to remote server:\nSELECT u.name, o.total\nFROM remote_users u\nJOIN remote_orders o ON o.user_id = u.id\nWHERE o.status = 'pending';\n\n-- Verify pushdown with EXPLAIN VERBOSE:\nEXPLAIN VERBOSE\nSELECT u.name, o.total\nFROM remote_users u\nJOIN remote_orders o ON o.user_id = u.id;\n-- Shows: Remote SQL with JOIN", tags: ['advanced', 'postgres-fdw', 'join-local-foreign', 'remote-join'] },
  { id: 'pg-advanced-l2-075', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you handle NULL values safely in PL/pgSQL conditionals?', options: ['NULL is treated as FALSE in all conditionals', 'Use IS DISTINCT FROM instead of = or != for NULL-safe comparisons — since NULL = NULL returns NULL (not TRUE) and NULL != value returns NULL (not TRUE), standard comparison operators can produce unexpected results in conditional logic', 'NULL values are automatically converted to empty strings', 'Use the NVL function like in Oracle'], correctAnswer: 2, explanation: 'In SQL and PL/pgSQL, NULL represents an unknown value. Any comparison with NULL yields NULL (not TRUE or FALSE). This means IF x = NULL never evaluates to TRUE. Use IS NULL, IS NOT NULL, or IS DISTINCT FROM for NULL-safe comparisons. COALESCE provides default values for NULLs. IS DISTINCT FROM is particularly useful because it treats NULL as a comparable value (NULL IS DISTINCT FROM NULL returns FALSE).', codeSnippet: "DO $$\nDECLARE\n  a INTEGER := NULL;\n  b INTEGER := NULL;\nBEGIN\n  -- WRONG: never true!\n  IF a = NULL THEN RAISE NOTICE 'never'; END IF;\n  IF a = b THEN RAISE NOTICE 'never'; END IF;\n\n  -- CORRECT:\n  IF a IS NULL THEN RAISE NOTICE 'a is null'; END IF;\n\n  -- NULL-safe comparison:\n  IF a IS NOT DISTINCT FROM b THEN\n    RAISE NOTICE 'both null = equal'; -- fires!\n  END IF;\n\n  -- COALESCE for defaults:\n  RAISE NOTICE '%', COALESCE(a, 0); -- 0\n\n  -- In triggers:\n  IF NEW.email IS DISTINCT FROM OLD.email THEN\n    -- True even if one or both are NULL\n    RAISE NOTICE 'email changed';\n  END IF;\nEND;\n$$;", tags: ['advanced', 'plpgsql', 'null-handling', 'is-distinct-from'] },
  { id: 'pg-advanced-l2-076', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'Triggers', question: 'How do you create a trigger that enforces cross-table business rules?', options: ['Use CHECK constraints across tables', 'Use foreign key constraints with custom checks', 'Create a trigger function that queries other tables to validate the operation — since CHECK constraints cannot reference other tables, triggers are the mechanism for enforcing complex multi-table business rules at the database level', 'Cross-table rules can only be enforced in application code'], correctAnswer: 3, explanation: 'Triggers fill the gap where declarative constraints (CHECK, FK, UNIQUE) are insufficient. Complex business rules like "an order cannot exceed the customer credit limit" or "a department cannot have more than N employees" require querying other tables, which triggers can do. Using BEFORE triggers allows rejecting operations before they are written. This ensures data integrity regardless of which application modifies the data.', codeSnippet: "-- Enforce: order total cannot exceed credit limit\nCREATE FUNCTION check_credit_limit()\nRETURNS TRIGGER AS $$\nDECLARE\n  credit_limit NUMERIC;\n  current_total NUMERIC;\nBEGIN\n  SELECT c.credit_limit INTO credit_limit\n  FROM customers c WHERE c.id = NEW.customer_id;\n\n  SELECT COALESCE(SUM(total), 0) INTO current_total\n  FROM orders\n  WHERE customer_id = NEW.customer_id\n    AND status != 'cancelled';\n\n  IF current_total + NEW.total > credit_limit THEN\n    RAISE EXCEPTION\n      'Order exceeds credit limit: current=%, new=%, limit=%',\n      current_total, NEW.total, credit_limit;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_credit_check\n  BEFORE INSERT ON orders\n  FOR EACH ROW\n  EXECUTE FUNCTION check_credit_limit();", tags: ['advanced', 'triggers', 'cross-table-rules', 'business-logic'] },
  { id: 'pg-advanced-l2-077', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'LISTEN/NOTIFY', question: 'What happens to LISTEN/NOTIFY when using connection pooling?', options: ['Connection pooling has no effect on LISTEN/NOTIFY', 'LISTEN/NOTIFY is automatically forwarded through poolers', 'Connection poolers in transaction mode (like PgBouncer) break LISTEN/NOTIFY because sessions are shared — LISTEN is a session-level command, and when the connection returns to the pool, the listening state is lost or notifications go to the wrong client', 'You must use a special pooler for LISTEN/NOTIFY'], correctAnswer: 0, explanation: 'LISTEN registers a channel on the PostgreSQL session. In transaction pooling mode, the connection returns to the pool after each transaction, losing the LISTEN registration. Even in session pooling mode, notifications may be delayed or lost during connection switches. The solution is to use a dedicated non-pooled connection for LISTEN, or use PgBouncer in session mode for listening connections.', codeSnippet: "-- Problem with PgBouncer in transaction mode:\n-- Connection A: LISTEN my_channel;\n-- (transaction ends, connection returns to pool)\n-- Connection B gets the same backend connection\n-- Notifications go to B instead of A!\n\n-- Solutions:\n\n-- 1. Dedicated connection for LISTEN:\n-- Use a separate, non-pooled connection\n-- for LISTEN operations\n\n-- 2. PgBouncer session mode for listeners:\n-- [databases]\n-- mydb_listen = host=localhost\n--   pool_mode=session\n-- mydb = host=localhost\n--   pool_mode=transaction\n\n-- 3. Use pg_listen extension or\n-- application-level polling as fallback\n\n-- 4. Check connection validity:\nSELECT pg_listening_channels();\n-- Returns array of channels being listened to", tags: ['advanced', 'listen-notify', 'connection-pooling', 'pgbouncer'] },
  { id: 'pg-advanced-l2-078', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you write a recursive function in PL/pgSQL?', options: ['Recursion is not supported in PL/pgSQL', 'Use RECURSIVE keyword in the function definition', 'Simply call the function within its own body — PL/pgSQL supports direct recursion where a function calls itself, and indirect recursion where function A calls function B which calls function A, subject to the max_stack_depth limit', 'Use a CTE with RECURSIVE instead'], correctAnswer: 1, explanation: 'PL/pgSQL functions can call themselves recursively. PostgreSQL tracks the stack depth and throws an error if max_stack_depth is exceeded (default 2MB). Recursive functions must have a base case to terminate. While recursive CTEs are often preferred for tree/graph traversal in SQL, PL/pgSQL recursion is useful for complex procedural logic that cannot be expressed in a single SQL query.', codeSnippet: "-- Recursive factorial:\nCREATE FUNCTION factorial(n BIGINT)\nRETURNS BIGINT AS $$\nBEGIN\n  IF n <= 1 THEN\n    RETURN 1;  -- base case\n  END IF;\n  RETURN n * factorial(n - 1);  -- recursive call\nEND;\n$$ LANGUAGE plpgsql IMMUTABLE;\n\nSELECT factorial(10); -- 3628800\n\n-- Recursive tree traversal:\nCREATE FUNCTION get_descendants(parent_id INT)\nRETURNS SETOF categories AS $$\nDECLARE\n  child RECORD;\nBEGIN\n  FOR child IN\n    SELECT * FROM categories WHERE parent = parent_id\n  LOOP\n    RETURN NEXT child;\n    -- Recurse into children:\n    RETURN QUERY\n      SELECT * FROM get_descendants(child.id);\n  END LOOP;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'plpgsql', 'recursion', 'recursive-function'] },
  { id: 'pg-advanced-l2-079', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'Materialized Views', question: 'What is the performance impact of REFRESH MATERIALIZED VIEW CONCURRENTLY vs regular refresh?', options: ['CONCURRENTLY is always faster', 'Regular refresh is the slower option since it rewrites the entire view while CONCURRENTLY does an incremental update', 'CONCURRENTLY is slower than regular refresh because it must compute the diff between old and new data — but it allows reads during the refresh, making it better for high-availability scenarios despite the extra computation', 'There is no performance difference'], correctAnswer: 2, explanation: 'Regular REFRESH truncates and repopulates the materialized view, which is faster in raw computation but takes an exclusive lock blocking all reads. CONCURRENTLY computes new data into a temporary area, diffs it against the current data, and applies changes. This diffing adds overhead (sometimes 2x slower) but readers can continue querying the old data during the process. Choose based on your availability requirements.', codeSnippet: "-- Regular refresh: faster but blocks reads\n\\timing on\nREFRESH MATERIALIZED VIEW mv_large;\n-- Time: 5000 ms\n-- During refresh: SELECT blocked!\n\n-- Concurrent refresh: slower but non-blocking\nREFRESH MATERIALIZED VIEW CONCURRENTLY mv_large;\n-- Time: 8000 ms (slower due to diff)\n-- During refresh: SELECT works with old data!\n\n-- Monitor refresh progress:\nSELECT pid, query, state, wait_event_type\nFROM pg_stat_activity\nWHERE query LIKE '%REFRESH%';\n\n-- Lock comparison:\n-- Regular: AccessExclusiveLock (blocks everything)\n-- CONCURRENTLY: ExclusiveLock (blocks writes only)", tags: ['advanced', 'materialized-views', 'concurrently-performance', 'locking'] },
  { id: 'pg-advanced-l2-080', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you create an anonymous code block with DO?', options: ['Use EXEC to run anonymous PL/pgSQL', 'DO $$ BEGIN ... END; $$ executes an anonymous PL/pgSQL block without creating a persistent function — useful for one-time scripts, migrations, and ad-hoc procedural logic that does not need to be stored in the database catalog', 'Anonymous blocks are not supported', 'Use EXECUTE BLOCK syntax'], correctAnswer: 3, explanation: 'DO blocks execute PL/pgSQL (or other procedural language) code without creating a function. They support the full PL/pgSQL syntax including variables, loops, conditions, and exception handling. DO blocks cannot return values and always run as the current user. They are ideal for one-off data migrations, complex administrative tasks, and testing PL/pgSQL code before wrapping it in a function.', codeSnippet: "-- Simple DO block:\nDO $$\nDECLARE\n  r RECORD;\nBEGIN\n  FOR r IN SELECT tablename FROM pg_tables\n    WHERE schemaname = 'public'\n  LOOP\n    RAISE NOTICE 'Table: %', r.tablename;\n    EXECUTE format(\n      'ANALYZE %I', r.tablename\n    );\n  END LOOP;\n  RAISE NOTICE 'All tables analyzed';\nEND;\n$$;\n\n-- Specify language:\nDO $body$\nBEGIN\n  IF NOT EXISTS (\n    SELECT FROM pg_tables WHERE tablename = 'config'\n  ) THEN\n    CREATE TABLE config (key TEXT, value TEXT);\n    INSERT INTO config VALUES ('version', '1.0');\n  END IF;\nEND;\n$body$ LANGUAGE plpgsql;", tags: ['advanced', 'plpgsql', 'do-block', 'anonymous-block'] },
  { id: 'pg-advanced-l2-081', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'Triggers', question: 'How do you use triggers for maintaining denormalized data?', options: ['Denormalization should never be done in a database', 'Use materialized views exclusively', 'Create triggers that automatically update denormalized columns or tables when source data changes — this keeps redundant data synchronized at the database level, ensuring consistency regardless of which application modifies the source data', 'Use application-level caching instead'], correctAnswer: 0, explanation: 'Denormalization improves read performance by storing pre-computed or duplicated data. Triggers ensure this data stays synchronized. Common patterns include: maintaining a full_name column from first_name and last_name, keeping a cached count column, or maintaining a search vector column. The key advantage over application-level sync is that the database guarantees consistency.', codeSnippet: "-- Keep a cached item_count on orders:\nCREATE FUNCTION sync_order_count()\nRETURNS TRIGGER AS $$\nBEGIN\n  IF TG_OP = 'INSERT' THEN\n    UPDATE orders SET item_count = item_count + 1\n    WHERE id = NEW.order_id;\n  ELSIF TG_OP = 'DELETE' THEN\n    UPDATE orders SET item_count = item_count - 1\n    WHERE id = OLD.order_id;\n  ELSIF TG_OP = 'UPDATE'\n    AND OLD.order_id != NEW.order_id THEN\n    UPDATE orders SET item_count = item_count - 1\n    WHERE id = OLD.order_id;\n    UPDATE orders SET item_count = item_count + 1\n    WHERE id = NEW.order_id;\n  END IF;\n  RETURN NULL;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_sync_count\n  AFTER INSERT OR UPDATE OR DELETE ON order_items\n  FOR EACH ROW\n  EXECUTE FUNCTION sync_order_count();", tags: ['advanced', 'triggers', 'denormalization', 'cached-columns'] },
  { id: 'pg-advanced-l2-082', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'postgres_fdw', question: 'How do you handle errors and timeouts with postgres_fdw?', options: ['postgres_fdw retries automatically on failure', 'Errors on the remote server always crash the local server', 'Use statement_timeout and connect_timeout options on the foreign server — remote errors are propagated as local errors that can be caught in exception handlers, and connection/statement timeouts prevent hanging queries', 'Error handling is not possible with foreign tables'], correctAnswer: 1, explanation: 'postgres_fdw propagates remote errors to the local session, where they can be caught in PL/pgSQL exception blocks. Connection timeouts (connect_timeout) prevent hanging during connection establishment. Statement timeouts can be set locally or as server options. If a remote server becomes unreachable, queries against foreign tables will fail with a connection error. You can use exception handlers to provide fallback behavior.', codeSnippet: "-- Set connection timeout:\nALTER SERVER remote_db\n  OPTIONS (ADD connect_timeout '10');\n\n-- Set keepalive options:\nALTER SERVER remote_db\n  OPTIONS (\n    ADD keepalives '1',\n    ADD keepalives_idle '30',\n    ADD keepalives_interval '10',\n    ADD keepalives_count '3'\n  );\n\n-- Handle remote errors in PL/pgSQL:\nCREATE FUNCTION safe_remote_query()\nRETURNS SETOF remote_users AS $$\nBEGIN\n  RETURN QUERY SELECT * FROM remote_users;\nEXCEPTION\n  WHEN connection_exception THEN\n    RAISE WARNING 'Remote server unavailable';\n    -- Return from cache or empty:\n    RETURN QUERY SELECT * FROM cached_users;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'postgres-fdw', 'error-handling', 'timeouts'] },
  { id: 'pg-advanced-l2-083', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'What is the difference between LANGUAGE plpgsql and LANGUAGE sql for functions?', options: ['They are identical — just two names for the same language', 'LANGUAGE sql can only do SELECT queries', 'LANGUAGE sql functions contain plain SQL statements and are inlined by the optimizer, while LANGUAGE plpgsql functions support procedural logic (variables, loops, conditionals) but cannot be inlined — SQL functions are preferred for simple operations', 'LANGUAGE plpgsql is deprecated in favor of sql'], correctAnswer: 2, explanation: 'SQL-language functions contain one or more SQL statements without procedural wrappers. The optimizer can inline SQL functions (replacing the function call with its body) which enables better optimization. PL/pgSQL functions provide procedural capabilities but are treated as black boxes by the optimizer. For simple functions that just wrap a query, LANGUAGE sql is preferred. For complex logic, use LANGUAGE plpgsql.', codeSnippet: "-- SQL function (can be inlined):\nCREATE FUNCTION active_users()\nRETURNS SETOF users\nLANGUAGE sql STABLE AS $$\n  SELECT * FROM users WHERE active = TRUE;\n$$;\n\n-- Equivalent PL/pgSQL (NOT inlined):\nCREATE FUNCTION active_users_plpgsql()\nRETURNS SETOF users\nLANGUAGE plpgsql STABLE AS $$\nBEGIN\n  RETURN QUERY SELECT * FROM users WHERE active = TRUE;\nEND;\n$$;\n\n-- SQL function with parameters:\nCREATE FUNCTION full_name(users)\nRETURNS TEXT\nLANGUAGE sql IMMUTABLE AS $$\n  SELECT $1.first_name || ' ' || $1.last_name;\n$$;\n\n-- Can use as computed column:\nSELECT u.id, full_name(u) FROM users u;", tags: ['advanced', 'plpgsql', 'language-sql', 'function-inlining'] },
  { id: 'pg-advanced-l2-084', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'Triggers', question: 'How do you create a trigger that prevents table truncation?', options: ['Use a CHECK constraint to prevent TRUNCATE', 'Use REVOKE TRUNCATE privilege', 'Create a BEFORE TRUNCATE trigger on the table — it fires before the TRUNCATE operation and can raise an exception to prevent it, providing a safety mechanism for critical tables that should never be truncated', 'TRUNCATE cannot be intercepted by triggers'], correctAnswer: 3, explanation: 'TRUNCATE triggers are statement-level (FOR EACH STATEMENT) since TRUNCATE affects all rows at once, not individual rows. A BEFORE TRUNCATE trigger can raise an exception to prevent the truncation. This is useful as a safety net for production tables. Note that NEW and OLD are not available in TRUNCATE triggers. AFTER TRUNCATE triggers are useful for cleanup or notification after a truncation occurs.', codeSnippet: "-- Prevent truncation of critical tables:\nCREATE FUNCTION prevent_truncate()\nRETURNS TRIGGER AS $$\nBEGIN\n  RAISE EXCEPTION\n    'TRUNCATE is not allowed on table %',\n    TG_TABLE_NAME\n    USING HINT = 'Use DELETE with WHERE instead';\n  RETURN NULL;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_no_truncate\n  BEFORE TRUNCATE ON critical_data\n  FOR EACH STATEMENT\n  EXECUTE FUNCTION prevent_truncate();\n\n-- Test:\nTRUNCATE critical_data;\n-- ERROR: TRUNCATE is not allowed on table critical_data\n-- HINT: Use DELETE with WHERE instead\n\n-- AFTER TRUNCATE for cleanup:\nCREATE TRIGGER trg_after_truncate\n  AFTER TRUNCATE ON staging_data\n  FOR EACH STATEMENT\n  EXECUTE FUNCTION notify_truncation();", tags: ['advanced', 'triggers', 'truncate-trigger', 'safety'] },
  { id: 'pg-advanced-l2-085', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you use ASSERT in PL/pgSQL for debugging?', options: ['ASSERT is not available in PL/pgSQL', 'Use RAISE EXCEPTION for assertions', 'ASSERT condition, message checks a condition and raises ASSERT_FAILURE if it is false — controlled by the plpgsql.check_asserts setting, it provides a way to add development-time checks that can be disabled in production for zero overhead', 'Use the CHECK constraint for assertions'], correctAnswer: 0, explanation: 'ASSERT (added in PostgreSQL 9.5) is a debugging tool for PL/pgSQL. When plpgsql.check_asserts is on (default), ASSERT evaluates the condition and raises ASSERT_FAILURE if false. When set to off, ASSERT statements are completely skipped with zero overhead. This makes it safe to leave assertions in production code. The error message is optional and supports format() style placeholders.', codeSnippet: "CREATE FUNCTION transfer_funds(\n  from_id INT, to_id INT, amount NUMERIC\n) RETURNS VOID AS $$\nDECLARE\n  from_balance NUMERIC;\nBEGIN\n  -- Debug assertions:\n  ASSERT amount > 0, 'Amount must be positive: %', amount;\n  ASSERT from_id != to_id, 'Cannot transfer to same account';\n\n  SELECT balance INTO from_balance\n  FROM accounts WHERE id = from_id;\n\n  ASSERT from_balance IS NOT NULL,\n    'Account % not found', from_id;\n  ASSERT from_balance >= amount,\n    'Insufficient funds: % < %', from_balance, amount;\n\n  -- Perform transfer...\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Disable assertions in production:\nSET plpgsql.check_asserts = off;", tags: ['advanced', 'plpgsql', 'assert', 'debugging'] },
  { id: 'pg-advanced-l2-086', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'pg_trgm', question: 'How does pg_trgm handle multilingual text and Unicode?', options: ['pg_trgm only works with ASCII text', 'It requires special configuration for Unicode', 'pg_trgm works with any text encoding supported by the database including UTF-8 — it processes trigrams at the character level (not byte level), so Unicode characters like accented letters, CJK characters, and emoji are handled correctly in similarity calculations', 'It requires the unaccent extension for non-ASCII'], correctAnswer: 1, explanation: 'pg_trgm operates on characters, not bytes, so it naturally handles Unicode text. However, similarity scores may behave differently for different scripts — CJK characters (which carry more meaning per character) tend to have higher similarity scores for short strings. For accent-insensitive search, combine pg_trgm with the unaccent extension. The trigram generation uses the database encoding.', codeSnippet: "-- Works with Unicode natively:\nSELECT similarity('München', 'Munchen'); -- ~0.4\nSELECT similarity('café', 'cafe');       -- ~0.5\n\n-- Combine with unaccent for better matching:\nCREATE EXTENSION unaccent;\n\nCREATE INDEX idx_name_trgm ON users\n  USING gin (unaccent(name) gin_trgm_ops);\n\n-- Accent-insensitive fuzzy search:\nSELECT name, similarity(unaccent(name), unaccent('Müller'))\nFROM users\nWHERE unaccent(name) % unaccent('Müller')\nORDER BY similarity(unaccent(name), unaccent('Müller')) DESC;\n\n-- CJK text:\nSELECT show_trgm('東京');\nSELECT similarity('東京都', '東京');", tags: ['advanced', 'pg-trgm', 'unicode', 'multilingual'] },
  { id: 'pg-advanced-l2-087', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'LISTEN/NOTIFY', question: 'How do you monitor and debug LISTEN/NOTIFY channels?', options: ['Use pg_stat_activity to see which sessions are listening on which channels — combine with pg_listening_channels() to see channels for the current session and pg_notification_queue_usage() to monitor the notification queue fill level', 'There are no monitoring tools for LISTEN/NOTIFY', 'Use the pg_notify_monitor extension', 'Check the PostgreSQL server log only'], correctAnswer: 2, explanation: 'pg_listening_channels() returns the list of channels the current session is listening on. pg_notification_queue_usage() returns a fraction (0.0 to 1.0) indicating how full the notification queue is. pg_stat_activity shows active connections but does not directly show their LISTEN channels. For debugging, you can open a psql session, LISTEN on the channel, and observe notifications in real time.', codeSnippet: "-- Channels this session listens on:\nSELECT * FROM pg_listening_channels();\n\n-- Notification queue usage (0.0 to 1.0):\nSELECT pg_notification_queue_usage();\n-- 0.0 = empty, 1.0 = full (notifications will fail)\n\n-- Debug: listen in psql\n-- psql> LISTEN my_channel;\n-- psql> -- Wait for notifications...\n-- Asynchronous notification \"my_channel\"\n--   with payload \"test message\"\n\n-- Find sessions with active listens:\n-- (Indirect: check pg_stat_activity)\nSELECT pid, usename, application_name, state\nFROM pg_stat_activity\nWHERE state = 'idle'\n  AND pid IN (\n    SELECT pid FROM pg_locks\n    WHERE locktype = 'advisory'\n  );", tags: ['advanced', 'listen-notify', 'monitoring', 'debugging'] },
  { id: 'pg-advanced-l2-088', language: 'postgresql', level: 'level2', category: 'Advanced', subcategory: 'postgres_fdw', question: 'How do you use postgres_fdw for database sharding?', options: ['postgres_fdw does not support sharding', 'Use pg_shard extension instead', 'Combine postgres_fdw with table partitioning — create a partitioned table locally where each partition is a foreign table pointing to a different remote server, allowing transparent distribution of data across multiple PostgreSQL instances', 'Sharding requires a third-party tool like Citus'], correctAnswer: 3, explanation: 'PostgreSQL declarative partitioning combined with postgres_fdw enables a manual sharding setup. You create a partitioned table and define each partition as a foreign table on a different server. Queries against the parent table are automatically routed to the correct partition/server based on the partition key. The planner can push down filters and joins to the remote servers. This approach requires manual partition management.', codeSnippet: "-- Partitioned parent table:\nCREATE TABLE orders (\n  id BIGINT,\n  customer_id INT,\n  total NUMERIC,\n  region TEXT\n) PARTITION BY LIST (region);\n\n-- Foreign servers for each shard:\nCREATE SERVER shard_us FOREIGN DATA WRAPPER postgres_fdw\n  OPTIONS (host 'us-db', dbname 'orders');\nCREATE SERVER shard_eu FOREIGN DATA WRAPPER postgres_fdw\n  OPTIONS (host 'eu-db', dbname 'orders');\n\n-- Partitions as foreign tables:\nCREATE FOREIGN TABLE orders_us\n  PARTITION OF orders FOR VALUES IN ('US')\n  SERVER shard_us OPTIONS (table_name 'orders');\n\nCREATE FOREIGN TABLE orders_eu\n  PARTITION OF orders FOR VALUES IN ('EU')\n  SERVER shard_eu OPTIONS (table_name 'orders');\n\n-- Transparent queries:\nSELECT * FROM orders WHERE region = 'US';\n-- Automatically routed to shard_us", tags: ['advanced', 'postgres-fdw', 'sharding', 'partitioning'] },
];

export default questions;
